(() => {
  'use strict';

  const DATA = window.GAME_DATA;
  const SAVE_KEY = 'triathlon-karriere-save-v1';
  const BACKUP_KEY = 'triathlon-karriere-backup-v1';
  const SAVE_VERSION = 7;
  const RARITY_NAMES = { common:'Gewöhnlich', uncommon:'Ungewöhnlich', rare:'Selten', epic:'Episch', legendary:'Legendär', unique:'Einzigartig' };
  const STAT_NAMES = { swim:'Schwimmen', bike:'Rad', run:'Laufen', transition:'Wechsel', tactic:'Taktik', aero:'Aero', reliability:'Zuverlässigkeit', comfort:'Komfort', stability:'Stabilität', handling:'Handling', heat:'Hitze', nutrition:'Verpflegung', organization:'Organisation', mental:'Mental' };
  const DISTANCE_FACTORS = { Supersprint:.24, Sprintdistanz:.4, Standarddistanz:.62, Mitteldistanz:.84, Langdistanz:1.1 };
  const GROUP_ICONS = { Schwimmen:'🏊', Radfahren:'🚴', Laufen:'🏃', Koppel:'↗', Regeneration:'☾', Mental:'◈', Spezial:'✦', Kraft:'◆', Technik:'◎' };

  const ui = {
    route:'home', trainingGroup:'Alle', raceSeries:'Alle', raceRegion:'Alle', gearTab:'equipment', moreTab:'skills', skillCategory:'Alle', questChain:'Alle', trainingTab:'plan',
    main:document.getElementById('mainContent'), dialog:document.getElementById('gameDialog'), dialogTitle:document.getElementById('dialogTitle'), dialogContent:document.getElementById('dialogContent'), toast:document.getElementById('toastRegion')
  };
  let deferredInstallPrompt = null;
  let state;
  let lastRenderedSecond = -1;

  const clamp = (v,min,max)=>Math.min(max,Math.max(min,v));
  const randomInt = (min,max)=>Math.floor(Math.random()*(max-min+1))+min;
  const pick = list=>list[Math.floor(Math.random()*list.length)];
  const formatMoney = v=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(Math.round(v));
  const formatNumber = v=>new Intl.NumberFormat('de-DE').format(Math.round(v));
  const escapeHtml = v=>String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c]));
  const audio = (name='click')=>window.GameAudio?.play(name);
  const haptic = (pattern=10)=>{if(state?.settings?.haptics&&navigator.vibrate)navigator.vibrate(pattern);};

  function formatDuration(totalSeconds) {
    const seconds=Math.max(0,Math.ceil(totalSeconds)); const h=Math.floor(seconds/3600); const m=Math.floor((seconds%3600)/60); const s=seconds%60;
    return h?`${h}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`:`${m}:${String(s).padStart(2,'0')}`;
  }
  function formatRaceTime(totalSeconds) {
    const seconds=Math.max(0,Math.round(totalSeconds)); const h=Math.floor(seconds/3600); const m=Math.floor((seconds%3600)/60); const s=seconds%60;
    return h?`${h}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`:`${m}:${String(s).padStart(2,'0')}`;
  }
  function todayKey(date=new Date()){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
  function weekKey(date=new Date()){ const d=new Date(date); const day=(d.getDay()+6)%7; d.setDate(d.getDate()-day); return todayKey(d); }
  function yesterdayKey(){const d=new Date();d.setDate(d.getDate()-1);return todayKey(d);}
  function hashText(text){let h=2166136261;for(let i=0;i<text.length;i++){h^=text.charCodeAt(i);h=Math.imul(h,16777619);}return Math.abs(h>>>0);}
  function xpForLevel(level){const n=Math.max(0,level-1);return Math.floor(78*n*n+92*n+Math.pow(n,2.28)*1.8);}
  function levelFromXp(xp){let level=1;while(level<99&&xp>=xpForLevel(level+1))level++;return level;}
  function skillLevel(id){return levelFromXp(state.skills[id]?.xp||0);}
  function skillProgress(id){const xp=state.skills[id]?.xp||0,level=levelFromXp(xp);if(level>=99)return{level,percent:100,current:xp,needed:xp};const start=xpForLevel(level),end=xpForLevel(level+1);return{level,percent:(xp-start)/(end-start)*100,current:xp-start,needed:end-start};}

  state = loadState();

  function makeDefaultState(){
    const starter={swimming:3,cycling:3,running:3,transitions:2,racecraft:2,endurance:3,strength:2,technique:3,recovery:2,mental:2,nutrition:2,mechanics:2,organization:2};
    const skills={}; Object.keys(DATA.skills).forEach(id=>skills[id]={xp:xpForLevel(starter[id]||1)});
    const equipped={}; Object.keys(DATA.equipmentSlots).forEach(slot=>equipped[slot]=null);
    Object.assign(equipped,{bike:'club_bike',helmet:'basic_helmet',shoes:'training_shoes',goggles:'basic_goggles'});
    return {
      version:SAVE_VERSION,gameVersion:DATA.version,createdAt:Date.now(),lastSavedAt:Date.now(),
      player:{name:'Rookie',money:480,reputation:0,fans:12,energy:100,fatigue:7,form:58,morale:74,careerDay:1,legacyPoints:0},
      season:{number:1,day:1,length:42,points:0,lastResult:null},
      skills, materials:{carbs:5,electrolytes:3,rubber:4,metal_parts:4,polymer:2,carbon_fiber:0,resin:0,blueprint:0,foam:2,textile_fiber:2,ceramic:0,electronics:0,titanium:0,botanical:1,data_chip:0,sealant:1},
      inventory:[{itemId:'club_bike',quantity:1},{itemId:'basic_helmet',quantity:1},{itemId:'training_shoes',quantity:1},{itemId:'basic_goggles',quantity:1}],
      itemMeta:{club_bike:{condition:92,quality:1,upgrade:0,mastery:0},basic_helmet:{condition:100,quality:1,upgrade:0,mastery:0},training_shoes:{condition:96,quality:1,upgrade:0,mastery:0},basic_goggles:{condition:100,quality:1,upgrade:0,mastery:0}},
      equipped,actions:{athlete:null,workshop:null,career:null},counters:{race_finishes:0,race_wins:0,rivals_beaten:0,long_finishes:0,craft_total:0,career_actions:0,training_actions:0,long_actions:0,sponsor_contracts:0,season_titles:0,international_finishes:0},
      raceHistory:[],raceRecords:{},raceMastery:{},rivalRelations:{},claimedQuests:[],claimedAchievements:[],
      sponsor:{id:null,baseline:0,level:1,contracts:0},focusId:'balanced',facilities:{workshop:0,recovery:0,media:0,lab:0,academy:0,warehouse:0},
      activePerks:[],loadouts:{sprint:null,middle:null,long:null},seenItems:['club_bike','basic_helmet','training_shoes','basic_goggles'],
      world:{current:'home',visited:['home']},daily:null,weekly:null,legacy:{learning:0,recovery:0,finance:0,scouting:0},log:[],
      trainingCycle:{number:1,loads:{swim:0,bike:0,run:0,strength:0,recovery:0,race:0},lastScore:null,lastSummary:null},targetRaceId:null,market:{date:null,deals:[],purchases:{}},pendingDecision:null,
      settings:{tutorialDone:false,setupDone:false,reducedMotion:false,sound:true,music:false,haptics:true,soundVolume:.45,musicVolume:.12}
    };
  }

  function mergeState(defaults,saved){
    if(!saved||typeof saved!=='object')return defaults;
    const merged=structuredClone(defaults); Object.assign(merged,saved);
    for(const key of ['player','season','skills','materials','equipped','actions','counters','facilities','loadouts','world','legacy','settings','trainingCycle','market']) merged[key]={...defaults[key],...(saved[key]||{})};
    merged.trainingCycle.loads={...defaults.trainingCycle.loads,...(saved.trainingCycle?.loads||{})};
    merged.market.purchases={...(saved.market?.purchases||{})};
    Object.keys(defaults.skills).forEach(id=>merged.skills[id]={...defaults.skills[id],...(saved.skills?.[id]||{})});
    Object.keys(DATA.equipmentSlots).forEach(slot=>{if(!(slot in merged.equipped))merged.equipped[slot]=null;});
    merged.inventory=Array.isArray(saved.inventory)?saved.inventory.filter(x=>DATA.items[x.itemId]&&x.quantity>0):defaults.inventory;
    merged.itemMeta={...defaults.itemMeta,...(saved.itemMeta||{})};
    merged.raceHistory=Array.isArray(saved.raceHistory)?saved.raceHistory.slice(0,100):[]; merged.raceRecords=saved.raceRecords||{}; merged.raceMastery=saved.raceMastery||{};
    merged.rivalRelations=saved.rivalRelations||{}; merged.claimedQuests=Array.isArray(saved.claimedQuests)?saved.claimedQuests:[]; merged.claimedAchievements=Array.isArray(saved.claimedAchievements)?saved.claimedAchievements:[];
    merged.activePerks=Array.isArray(saved.activePerks)?saved.activePerks.filter(id=>DATA.perks[id]):[]; merged.seenItems=Array.isArray(saved.seenItems)?saved.seenItems.filter(id=>DATA.items[id]):defaults.seenItems;
    merged.log=Array.isArray(saved.log)?saved.log.slice(0,40):[];
    if(saved.sponsorId&&!saved.sponsor) merged.sponsor={id:saved.sponsorId,baseline:saved.counters?.race_finishes||0,level:1,contracts:0}; else merged.sponsor={...defaults.sponsor,...(saved.sponsor||{})};
    if(saved.player?.seasonPoints&&!saved.season) merged.season.points=saved.player.seasonPoints;
    merged.world.current=DATA.regions[merged.world.current]?merged.world.current:'home'; merged.world.visited=(merged.world.visited||['home']).filter(id=>DATA.regions[id]); if(!merged.world.visited.includes('home'))merged.world.visited.push('home');
    merged.version=SAVE_VERSION;merged.gameVersion=DATA.version;
    Object.entries(merged.actions).forEach(([slot,running])=>{if(running&&!getAction(slot,running.id))merged.actions[slot]=null;});
    return merged;
  }

  function loadState(){
    try{
      const parsed=JSON.parse(localStorage.getItem(SAVE_KEY)||'null'); const loaded=mergeState(makeDefaultState(),parsed); applyPassiveRecovery(loaded); ensureDaily(loaded);ensureWeekly(loaded);
      ensureTrainingCycle(loaded);ensureMarket(loaded);localStorage.setItem(SAVE_KEY,JSON.stringify(loaded));return loaded;
    }catch(error){console.warn(error);const fresh=makeDefaultState();ensureDaily(fresh);ensureWeekly(fresh);ensureTrainingCycle(fresh);ensureMarket(fresh);return fresh;}
  }
  function applyPassiveRecovery(target){
    const elapsed=Math.min(12*3600,Math.max(0,(Date.now()-(target.lastSavedAt||Date.now()))/1000));
    target.player.energy=clamp(target.player.energy+elapsed/900,0,100); target.player.fatigue=clamp(target.player.fatigue-elapsed/2700,0,100); target.lastSavedAt=Date.now();
  }
  function saveState(){state.lastSavedAt=Date.now();state.gameVersion=DATA.version;localStorage.setItem(SAVE_KEY,JSON.stringify(state));updateHeader();}
  function autoBackup(){try{localStorage.setItem(BACKUP_KEY,JSON.stringify(state));}catch(_){} }
  function logEvent(text,icon='•'){state.log.unshift({text,icon,time:Date.now()});state.log=state.log.slice(0,40);}

  function generateDaily(key,target){
    const pool=[...DATA.dailyMissionPool],chosen=[],seed=hashText(key);for(let i=0;i<3;i++){const ix=(seed+i*7919)%pool.length;chosen.push(pool.splice(ix,1)[0]);}
    return{date:key,missions:chosen.map(m=>({...m,start:counterValue(m.counter,target)})),claimed:[],bonusClaimed:false,streak:target.daily?.lastCompletedDate===yesterdayKey()?(target.daily?.streak||0):0,lastCompletedDate:target.daily?.lastCompletedDate||null};
  }
  function ensureDaily(target=state){const key=todayKey();if(!target.daily||target.daily.date!==key)target.daily=generateDaily(key,target);}
  function generateWeekly(key,target){const pool=[...DATA.weeklyMissionPool],seed=hashText(key+'weekly'),chosen=[];for(let i=0;i<2;i++){const ix=(seed+i*3571)%pool.length;chosen.push(pool.splice(ix,1)[0]);}return{date:key,missions:chosen.map(m=>({...m,starts:Object.fromEntries(m.requirements.map(r=>[r.counter,counterValue(r.counter,target)]))})),claimed:[]};}
  function ensureWeekly(target=state){const key=weekKey();if(!target.weekly||target.weekly.date!==key)target.weekly=generateWeekly(key,target);}

  const LOAD_LABELS={swim:'Schwimmen',bike:'Rad',run:'Laufen',strength:'Kraft',recovery:'Erholung',race:'Racecraft'};
  function careerCycleNumber(target=state){return Math.max(1,Math.floor(((target.player?.careerDay||1)-1)/7)+1);}
  function emptyTrainingLoads(){return{swim:0,bike:0,run:0,strength:0,recovery:0,race:0};}
  function ensureTrainingCycle(target=state){const number=careerCycleNumber(target);if(!target.trainingCycle||target.trainingCycle.number!==number)target.trainingCycle={number,loads:emptyTrainingLoads(),lastScore:target.trainingCycle?.lastScore??null,lastSummary:target.trainingCycle?.lastSummary??null};target.trainingCycle.loads={...emptyTrainingLoads(),...(target.trainingCycle.loads||{})};}
  function trainingTargets(target=state){return DATA.trainingTargets[target.focusId]||DATA.trainingTargets.balanced;}
  function inferTrainingLoad(action){if(action.trainingLoad)return action.trainingLoad;const load=emptyTrainingLoads(),xp=action.xp||{};load.swim=(xp.swimming||0)/6;load.bike=(xp.cycling||0)/6;load.run=(xp.running||0)/6;load.strength=(xp.strength||0)/5;load.recovery=Math.max(0,(-(action.fatigue||0))*3+(xp.recovery||0)/5);load.race=((xp.racecraft||0)+(xp.transitions||0)*.6+(xp.mental||0)*.25)/6;return Object.fromEntries(Object.entries(load).filter(([,v])=>v>0));}
  function recordTrainingLoad(action){ensureTrainingCycle();const load=inferTrainingLoad(action);Object.entries(load).forEach(([key,value])=>state.trainingCycle.loads[key]=(state.trainingCycle.loads[key]||0)+Math.round(value));}
  function trainingBalance(target=state){ensureTrainingCycle(target);const targets=trainingTargets(target),loads=target.trainingCycle.loads||emptyTrainingLoads();const keys=Object.keys(targets),ratios=keys.map(k=>(loads[k]||0)/Math.max(1,targets[k]));const coverage=ratios.reduce((sum,r)=>sum+Math.min(1,r),0)/keys.length;const overload=Math.max(0,ratios.reduce((m,r)=>Math.max(m,r),0)-1.25);const totalRatio=Object.values(loads).reduce((a,b)=>a+b,0)/Math.max(1,Object.values(targets).reduce((a,b)=>a+b,0));const score=clamp(Math.round(coverage*92+Math.min(1,totalRatio)*8-overload*45),0,100);return{score,coverage,totalRatio,overload,loads,targets};}
  function settleTrainingCycle(){const result=trainingBalance();state.trainingCycle.lastScore=result.score;state.trainingCycle.lastSummary={score:result.score,loads:{...result.loads},targets:{...result.targets}};if(result.score>=72&&result.totalRatio>=.72&&result.overload<.18){state.counters.balanced_weeks=(state.counters.balanced_weeks||0)+1;state.player.form=clamp(state.player.form+3,0,100);state.player.morale=clamp(state.player.morale+2,0,100);logEvent(`Trainingszyklus ${state.trainingCycle.number}: ausgewogen (${result.score} %).`,'📊');}else if(result.overload>.3){state.player.fatigue=clamp(state.player.fatigue+6,0,100);state.player.form=clamp(state.player.form-3,0,100);logEvent(`Trainingszyklus ${state.trainingCycle.number}: Überlastung erkannt.`,'⚠');}else logEvent(`Trainingszyklus ${state.trainingCycle.number}: ${result.score} % Planabdeckung.`,'📊');}
  function trainingRaceMultiplier(){const current=trainingBalance().score,last=state.trainingCycle.lastScore??60,score=Math.max(current*.55,last*.45);return clamp(.965+(score/100)*.07,.965,1.035);}
  function deterministicMarketDeals(key,target=state){const unlocked=DATA.shop.map((entry,index)=>({entry,index}));let seed=hashText(`${key}-${target.season.number}-${target.player.reputation}`),pool=[...unlocked],deals=[];for(let i=0;i<Math.min(10,pool.length);i++){const ix=(seed+i*1877)%pool.length,selected=pool.splice(ix,1)[0],discount=[0,.08,.12,.18][(seed+i*17)%4];deals.push({index:selected.index,discount,stock:selected.entry.type==='item'?1:3});}return deals;}
  function ensureMarket(target=state){const key=todayKey();if(!target.market||target.market.date!==key)target.market={date:key,deals:deterministicMarketDeals(key,target),purchases:{}};if(!Array.isArray(target.market.deals)||!target.market.deals.length)target.market.deals=deterministicMarketDeals(key,target);target.market.purchases=target.market.purchases||{};}
  function targetRace(){return DATA.races.find(r=>r.id===state.targetRaceId)||null;}
  function setTargetRace(id){const race=DATA.races.find(r=>r.id===id);if(!race)return;const first=!state.targetRaceId;state.targetRaceId=id;if(first)state.counters.target_selected=(state.counters.target_selected||0)+1;logEvent(`${race.name} als Zielrennen gesetzt.`,'🎯');audio('goal');haptic([15,25,15]);saveState();toast(`${race.name} ist jetzt dein Zielrennen.`,'success');render();}
  function readinessBreakdown(race){const body=clamp(Math.round(readiness()*92),0,100);const skill=clamp(Math.round((racePowerEstimate(race)/Math.max(1,race.difficulty))*72),0,100);const gear=clamp(Math.round(45+Object.values(equipmentStats()).reduce((a,b)=>a+Math.max(0,b),0)*1.2),0,100);const plan=clamp(Math.round(trainingRaceMultiplier()*100-2),0,100);const logistics=state.world.current===race.region?100:Math.max(35,85-skillLevel('organization'));const total=Math.round(body*.31+skill*.31+gear*.16+plan*.15+logistics*.07);return{body,skill,gear,plan,logistics,total};}
  function coachNextAction(){const race=targetRace();if(state.player.fatigue>70)return DATA.athleteActions.find(a=>['mobility_reset','recovery_session','deep_recovery'].includes(a.id)&&actionRequirementsMet(a));if(race){const weights=raceWeights(race);const options=[['swimming',weights.swim],['cycling',weights.bike],['running',weights.run]].sort((a,b)=>(skillLevel(a[0])/a[1])-(skillLevel(b[0])/b[1]));const skill=options[0][0];return DATA.athleteActions.filter(a=>a.xp?.[skill]&&actionRequirementsMet(a)).sort((a,b)=>(b.xp[skill]||0)-(a.xp[skill]||0))[0];}return null;}

  function perkSlots(){return 3+(state.facilities.academy>=3?1:0);}
  function hasPerk(id){return state.activePerks.includes(id);}
  function perkEffect(key,defaultValue=1){let value=defaultValue;state.activePerks.forEach(id=>{const v=DATA.perks[id]?.effect?.[key];if(typeof v==='number')value*=v;});return value;}
  function activeSponsor(){return DATA.sponsors.find(s=>s.id===state.sponsor.id)||null;}
  function currentRegion(){return DATA.regions[state.world.current]||DATA.regions.home;}
  function legacyMultiplier(key,step){return 1+(state.legacy[key]||0)*step;}
  function focusXpMultiplier(skillId){const f=DATA.focuses[state.focusId]||DATA.focuses.balanced;return f.xpSkills?.includes(skillId)?(state.focusId==='publicFigure'?1.12:1.1):1;}
  function regionXpMultiplier(skillId,action){const r=currentRegion();let mult=r.bonuses?.skills?.includes(skillId)?r.bonuses.xp||1:1;if(action&&r.bonuses?.trainingGroups?.includes(action.group))mult=Math.max(mult,r.bonuses.xp||1);return mult;}
  function addXp(skillId,amount,action=null,extra=1){if(!DATA.skills[skillId]||!amount)return;const before=skillLevel(skillId);let mult=focusXpMultiplier(skillId)*regionXpMultiplier(skillId,action)*legacyMultiplier('learning',.02)*extra;
    if(['materials','aerodynamics','productDevelopment'].includes(skillId))mult*=1+state.facilities.lab*.04;
    const trainingPerk=state.activePerks.map(id=>DATA.perks[id]).find(p=>p?.effect?.trainingXpSkills?.includes(skillId));if(trainingPerk)mult*=trainingPerk.effect.trainingXp;
    state.skills[skillId].xp+=Math.max(0,Math.round(amount*mult));const after=skillLevel(skillId);if(after>before){toast(`${DATA.skills[skillId].name} erreicht Level ${after}.`,'success');audio('level');}
  }

  function itemQuantity(id){return state.inventory.find(x=>x.itemId===id)?.quantity||0;}
  function getItemMeta(id){if(!state.itemMeta[id])state.itemMeta[id]={condition:100,quality:1,upgrade:0,mastery:0};return state.itemMeta[id];}
  function addItem(id,quantity=1,quality=1){if(!DATA.items[id])return;const existing=state.inventory.find(x=>x.itemId===id);if(existing)existing.quantity+=quantity;else state.inventory.push({itemId:id,quantity});if(DATA.items[id].slot){const meta=getItemMeta(id);meta.quality=Math.max(meta.quality||1,quality);meta.condition=Math.max(meta.condition||0,100);}if(!state.seenItems.includes(id)){state.seenItems.push(id);if(['epic','legendary','unique'].includes(DATA.items[id].rarity))audio('rare');}}
  function removeItem(id,quantity=1){const entry=state.inventory.find(x=>x.itemId===id);if(!entry||entry.quantity<quantity)return false;entry.quantity-=quantity;if(entry.quantity<=0)state.inventory=state.inventory.filter(x=>x!==entry);return true;}
  function hasMaterials(costs={}){return Object.entries(costs).every(([id,n])=>(state.materials[id]||0)>=n);}
  function hasItems(costs={}){return Object.entries(costs).every(([id,n])=>itemQuantity(id)>=n);}

  function requirementMet(req,target=state){
    if(!req)return true; const p=target.player||state.player;
    if(req.type==='finishes')return counterValue('race_finishes',target)>=req.value;
    if(req.type==='longFinishes')return counterValue('long_finishes',target)>=req.value;
    if(req.type==='wins')return counterValue('race_wins',target)>=req.value;
    if(req.type==='reputation')return p.reputation>=req.value;
    if(req.type==='fans')return p.fans>=req.value;
    if(req.type==='skill')return levelFromXp(target.skills?.[req.id]?.xp||0)>=req.value;
    if(req.type==='seasonPoints')return (target.season?.points||0)>=req.value;
    if(req.type==='raceTop')return (target.raceRecords?.[req.id]?.bestPlacement||999)<=req.value;
    if(req.type==='raceWin')return (target.raceRecords?.[req.id]?.wins||0)>=1;
    if(req.type==='facility')return (target.facilities?.[req.id]||0)>=req.value;
    if(req.type==='quest')return target.claimedQuests?.includes(req.id);
    return false;
  }
  function actionRequirementsMet(action){const r=action.requirements||{};if(r.skill&&skillLevel(r.skill[0])<r.skill[1])return false;if(r.reputation&&state.player.reputation<r.reputation)return false;if(r.fans&&state.player.fans<r.fans)return false;if(r.facility&&(state.facilities[r.facility[0]]||0)<r.facility[1])return false;if(r.region&&state.world.current!==r.region)return false;if(r.quest&&!state.claimedQuests.includes(r.quest))return false;return true;}
  function actionLockText(action){const r=action.requirements||{};if(r.skill&&skillLevel(r.skill[0])<r.skill[1])return `${DATA.skills[r.skill[0]].name} Level ${r.skill[1]}`;if(r.reputation&&state.player.reputation<r.reputation)return `${r.reputation} Reputation`;if(r.fans&&state.player.fans<r.fans)return `${formatNumber(r.fans)} Fans`;if(r.facility&&(state.facilities[r.facility[0]]||0)<r.facility[1])return `${DATA.facilities[r.facility[0]].name} Level ${r.facility[1]}`;if(r.region&&state.world.current!==r.region)return `Region ${DATA.regions[r.region]?.name}`;if(r.quest&&!state.claimedQuests.includes(r.quest))return `Quest ${DATA.quests.find(q=>q.id===r.quest)?.title||r.quest}`;return'';}
  function getAction(slot,id){const source=slot==='athlete'?DATA.athleteActions:slot==='workshop'?DATA.workshopActions:DATA.careerActions;return source.find(a=>a.id===id);}
  function actionDuration(slot,action){let duration=action.duration;if(slot==='workshop'){duration*=activeSponsor()?.effect?.workshopSpeed||1;duration*=1-state.facilities.workshop*.06;if(action.tags?.includes('Prototyp'))duration*=perkEffect('prototypeSpeed');}if(slot==='career')duration*=1-state.facilities.media*.025;return Math.max(12,Math.round(duration));}
  function actionEnergy(action){let energy=action.energy||0;if(energy<0&&action.calendarDays>=2&&hasPerk('volume_engine'))energy*=perkEffect('longEnergy');return Math.round(energy);}
  function startAction(slot,id){const action=getAction(slot,id);if(!action||state.actions[slot])return;if(!actionRequirementsMet(action))return toast(`Noch gesperrt: ${actionLockText(action)}.`,'error');const energy=actionEnergy(action);if(energy<0&&state.player.energy<Math.abs(energy))return toast('Nicht genug Energie. Plane Regeneration ein.','error');if(!hasMaterials(action.costs))return toast('Dir fehlen Materialien.','error');if(!hasItems(action.itemCosts))return toast('Dir fehlen benötigte Gegenstände.','error');
    Object.entries(action.costs||{}).forEach(([mat,n])=>state.materials[mat]-=n);Object.entries(action.itemCosts||{}).forEach(([item,n])=>removeItem(item,n));const duration=actionDuration(slot,action);state.actions[slot]={id,slot,startedAt:Date.now(),endsAt:Date.now()+duration*1000,costs:action.costs||{},itemCosts:action.itemCosts||{}};saveState();toast(`${action.title} gestartet.`);render();}
  function cancelAction(slot){const run=state.actions[slot];if(!run)return;Object.entries(run.costs||{}).forEach(([id,n])=>state.materials[id]=(state.materials[id]||0)+n);Object.entries(run.itemCosts||{}).forEach(([id,n])=>addItem(id,n));state.actions[slot]=null;saveState();toast('Aktion abgebrochen; Ressourcen zurückgegeben.');render();}

  function randomActionEvent(slot,action){const candidates=DATA.randomEvents.filter(e=>e.type===slot||e.type===(slot==='athlete'?'training':slot));for(const event of candidates){let chance=event.chance;if(slot==='workshop'&&activeSponsor()?.effect?.craftQuality)chance+=activeSponsor().effect.craftQuality*.12;if(Math.random()<chance)return event;}return null;}
  function awardMaterials(ranges,event){const gained=[];const baseBonus=state.facilities.workshop*.06+state.facilities.warehouse*.05+(hasPerk('material_whisperer') ? .12 : 0)+(activeSponsor()?.effect?.rareMaterial||0);Object.entries(ranges||{}).forEach(([id,range])=>{let amount=randomInt(range[0],range[1]);if(amount>0&&Math.random()<baseBonus)amount++;if(amount>0){state.materials[id]=(state.materials[id]||0)+amount;gained.push(`${amount}× ${DATA.materials[id]?.name||id}`);}});if(event?.effect?.material==='random'){const id=pick(Object.keys(DATA.materials));state.materials[id]=(state.materials[id]||0)+(event.effect.quantity||1);gained.push(`${event.effect.quantity||1}× ${DATA.materials[id].name}`);}return gained;}
  function craftQuality(action,event){let q=1+Math.floor(skillLevel('productDevelopment')/15)+Math.floor(state.facilities.lab/2);if(hasPerk('material_whisperer')&&Math.random()<.35)q++;if(activeSponsor()?.effect?.craftQuality&&Math.random()<activeSponsor().effect.craftQuality)q++;if(event?.effect?.quality)q+=event.effect.quality;return clamp(q,1,5);}
  function completeAction(slot,running,silent=false){const action=getAction(slot,running.id);if(!action){state.actions[slot]=null;return null;}const randomEvent=randomActionEvent(slot,action),decisionPool=DATA.decisionEvents?.filter(e=>e.type===slot)||[],decisionEvent=!state.pendingDecision?decisionPool.find(e=>Math.random()<e.chance):null,event=decisionEvent?null:randomEvent;let bonusXp=1+(event?.effect?.bonusXp||0);Object.entries(action.xp||{}).forEach(([id,n])=>addXp(id,n,action,bonusXp));
    let money=action.money||0,rep=action.reputation||0,fans=action.fans||0;if(slot==='career'){rep*=1+state.facilities.media*.06;fans*=1+state.facilities.media*.08;fans*=perkEffect('fans');state.counters.career_actions++;}money*=legacyMultiplier('finance',.03);state.player.money+=Math.round(money);state.player.reputation+=Math.round(rep);state.player.fans+=Math.round(fans+(event?.effect?.fans||0));
    state.player.energy=clamp(state.player.energy+actionEnergy(action),0,100);let fatigue=action.fatigue||0;if(action.id==='recovery_session'||action.id==='deep_recovery')fatigue*=1+state.facilities.recovery*.12;fatigue*=hasPerk('recovery_routine')&&fatigue<0?perkEffect('recovery'):1;state.player.fatigue=clamp(state.player.fatigue+fatigue+(event?.effect?.fatigue||0),0,100);state.player.form=clamp(state.player.form+(action.form||0)+(event?.effect?.form||0),0,100);state.player.morale=clamp(state.player.morale+(action.morale||0)+(event?.effect?.morale||0),0,100);
    const gained=awardMaterials(action.materials,event);if(event?.effect?.refund){Object.entries(running.costs||{}).forEach(([id,n])=>{const refund=Math.max(1,Math.floor(n*event.effect.refund));state.materials[id]=(state.materials[id]||0)+refund;gained.push(`${refund}× ${DATA.materials[id].name} zurückgewonnen`);});}
    if(action.item){const quality=slot==='workshop'?craftQuality(action,event):1;addItem(action.item[0],action.item[1],quality);gained.push(`${action.item[1]}× ${DATA.items[action.item[0]].name}${quality>1?` (Qualität ${quality})`:''}`);}
    state.counters[`action_${action.id}`]=(state.counters[`action_${action.id}`]||0)+1;if(slot==='workshop'){state.counters[`craft_${action.id}`]=(state.counters[`craft_${action.id}`]||0)+1;state.counters.craft_total++;}if(slot==='athlete'){state.counters.training_actions++;recordTrainingLoad(action);if(action.calendarDays>=2)state.counters.long_actions++;}
    state.actions[slot]=null;advanceCalendar(action.calendarDays||1);checkSponsorContract(false);const message=`${action.title} abgeschlossen${gained.length?` – ${gained.join(', ')}`:''}.`;logEvent(message,action.icon);if(event)logEvent(`${event.title}: ${event.text}`,'✦');if(decisionEvent){state.pendingDecision={eventId:decisionEvent.id,createdAt:Date.now()};logEvent(`${decisionEvent.title}: Entscheidung offen.`,'◇');}if(!silent)toast(event?`${message} ${event.title}!`:message,event?.effect?.quality?'rare':'success');return message;}
  function processCompletedActions(silent=false){const now=Date.now(),messages=[];Object.entries(state.actions).forEach(([slot,run])=>{if(run&&run.endsAt<=now){const m=completeAction(slot,run,silent);if(m)messages.push(m);}});if(messages.length)saveState();return messages;}

  function showPendingDecision(){if(!state.pendingDecision||ui.dialog.open)return;const event=DATA.decisionEvents?.find(e=>e.id===state.pendingDecision.eventId);if(!event){state.pendingDecision=null;saveState();return;}openDialog(event.title,`<div class="decision-event"><div class="decision-icon">◇</div><p>${event.text}</p><div class="decision-grid">${event.choices.map((choice,index)=>`<button type="button" class="decision-choice" data-decision-choice="${index}"><strong>${choice.label}</strong><small>${choice.description}</small></button>`).join('')}</div></div>`);}
  function applyDecisionEffect(effect={}){for(const key of ['money','reputation','fans','energy','fatigue','form','morale'])if(effect[key]){if(['money','reputation','fans'].includes(key))state.player[key]=Math.max(0,(state.player[key]||0)+effect[key]);else state.player[key]=clamp((state.player[key]||0)+effect[key],0,100);}Object.entries(effect.xp||{}).forEach(([id,n])=>addXp(id,n));Object.entries(effect.materials||{}).forEach(([id,n])=>state.materials[id]=Math.max(0,(state.materials[id]||0)+n));if(effect.item)addItem(effect.item[0],effect.item[1]||1);if(effect.counter)state.counters[effect.counter]=(state.counters[effect.counter]||0)+1;}
  function resolveDecision(index){const event=DATA.decisionEvents?.find(e=>e.id===state.pendingDecision?.eventId),choice=event?.choices?.[index];if(!event||!choice)return;applyDecisionEffect(choice.effect);state.counters.decisions_resolved=(state.counters.decisions_resolved||0)+1;logEvent(`${event.title}: ${choice.label}.`,'◇');state.pendingDecision=null;audio('decision');saveState();closeDialog();haptic([20,30,20]);toast('Entscheidung umgesetzt.','success');render();}

  function counterValue(id,target=state){return target.counters?.[id]||0;}
  function advanceCalendar(days){const oldCycle=careerCycleNumber();const newDay=state.player.careerDay+days;const newCycle=Math.max(1,Math.floor((newDay-1)/7)+1);if(newCycle>oldCycle)settleTrainingCycle();state.player.careerDay=newDay;state.season.day+=days;ensureTrainingCycle();while(state.season.day>state.season.length){state.season.day-=state.season.length;settleSeason();}}
  function settleSeason(){const tiers=[...DATA.seasonTiers].sort((a,b)=>a.min-b.min);let tier=tiers[0];tiers.forEach(t=>{if(state.season.points>=t.min)tier=t;});applyRewards(tier.reward,{silent:true});state.player.legacyPoints+=tier.legacy;if(tier.min>=340)state.counters.season_titles++;state.season.lastResult={season:state.season.number,points:state.season.points,tier:tier.name,legacy:tier.legacy};logEvent(`Saison ${state.season.number} beendet: ${tier.name}, +${tier.legacy} Legacy-Punkte.`,'🏆');state.season.number++;state.season.points=0;state.player.form=clamp(state.player.form-6,35,100);state.player.fatigue=clamp(state.player.fatigue-12,0,100);autoBackup();}
  function seasonTier(){let tier=DATA.seasonTiers[0];DATA.seasonTiers.forEach(t=>{if(state.season.points>=t.min)tier=t;});return tier;}
  function nextSeasonTier(){return DATA.seasonTiers.find(t=>t.min>state.season.points)||null;}

  function itemStats(id){const item=DATA.items[id],meta=getItemMeta(id);const condition=.72+(meta.condition||100)*.0028;const quality=1+((meta.quality||1)-1)*.055+(meta.upgrade||0)*.04;const mastery=1+Math.min(30,meta.mastery||0)*.001;const result={};Object.entries(item?.stats||{}).forEach(([k,v])=>result[k]=v*condition*quality*mastery);return result;}
  function equipmentStats(){const result={};Object.values(state.equipped).filter(Boolean).forEach(id=>Object.entries(itemStats(id)).forEach(([k,v])=>result[k]=(result[k]||0)+v));const sponsor=activeSponsor();if(sponsor?.effect?.aeroGear&&result.aero)result.aero*=sponsor.effect.aeroGear;if(sponsor?.effect?.runGear&&result.run)result.run*=sponsor.effect.runGear;if(sponsor?.effect?.swimGear&&result.swim)result.swim*=sponsor.effect.swimGear;return result;}
  function equipItem(id){const item=DATA.items[id];if(!item?.slot||itemQuantity(id)<1)return;state.equipped[item.slot]=id;saveState();toast(`${item.name} ausgerüstet.`);render();}
  function useItem(id){const item=DATA.items[id];if(!item?.consumable||!removeItem(id,1))return;if(item.consumable==='recovery'){state.player.fatigue=clamp(state.player.fatigue-13,0,100);state.player.energy=clamp(state.player.energy+9,0,100);state.player.morale=clamp(state.player.morale+2,0,100);toast('Regeneration verbessert.','success');}else return toast('Dieser Gegenstand wird in der Rennvorbereitung verwendet.');saveState();render();}
  function sellItem(id){const item=DATA.items[id];if(!item||item.value<=0||itemQuantity(id)<1)return;if(Object.values(state.equipped).includes(id))return toast('Ausgerüstete Items können nicht verkauft werden.','error');removeItem(id,1);state.player.money+=Math.round(item.value*.55);saveState();toast(`${item.name} verkauft.`);render();}
  function repairAll(){let cost=0;Object.keys(state.itemMeta).forEach(id=>{if(itemQuantity(id)<1)return;const meta=getItemMeta(id),item=DATA.items[id];cost+=(100-meta.condition)*(item?.value||100)/900;});cost=Math.max(0,Math.round(cost*(1-skillLevel('mechanics')*.004)));if(cost===0)return toast('Alle Ausrüstungsgegenstände sind in gutem Zustand.');if(state.player.money<cost)return toast(`Reparatur kostet ${formatMoney(cost)}.`,'error');state.player.money-=cost;Object.keys(state.itemMeta).forEach(id=>{if(itemQuantity(id))getItemMeta(id).condition=100;});addXp('mechanics',120);saveState();toast(`Ausrüstung für ${formatMoney(cost)} gewartet.`,'success');render();}
  function upgradeItem(id){const item=DATA.items[id],meta=getItemMeta(id);if(!item?.slot||itemQuantity(id)<1||meta.upgrade>=3)return;const rarityCost={common:100,uncommon:220,rare:480,epic:900,legendary:1600,unique:2000}[item.rarity]||200;const cost=Math.round(rarityCost*(meta.upgrade+1));const material=meta.upgrade>=1?'carbon_fiber':'metal_parts',needed=meta.upgrade+1;if(state.player.money<cost||(state.materials[material]||0)<needed)return toast(`Benötigt ${formatMoney(cost)} und ${needed}× ${DATA.materials[material].name}.`,'error');state.player.money-=cost;state.materials[material]-=needed;meta.upgrade++;meta.condition=100;state.counters.equipment_upgrades=(state.counters.equipment_upgrades||0)+1;state.counters.prototype_milestones=(state.counters.prototype_milestones||0)+1;addXp('mechanics',160*meta.upgrade);addXp('materials',90*meta.upgrade);saveState();toast(`${item.name} auf Upgrade +${meta.upgrade} verbessert.`,'rare');render();}
  function degradeEquipment(df){Object.values(state.equipped).filter(Boolean).forEach(id=>{const meta=getItemMeta(id);meta.condition=clamp(meta.condition-(1.2+df*4.2+Math.random()*1.5),20,100);meta.mastery=(meta.mastery||0)+1;state.counters.gear_mastery_uses=(state.counters.gear_mastery_uses||0)+1;});}
  function saveLoadout(id){state.loadouts[id]=structuredClone(state.equipped);saveState();toast('Ausrüstungsset gespeichert.');render();}
  function applyLoadout(id){const set=state.loadouts[id];if(!set)return;Object.entries(set).forEach(([slot,item])=>{if(!item||itemQuantity(item)>0)state.equipped[slot]=item;});state.counters.loadouts_applied=(state.counters.loadouts_applied||0)+1;saveState();toast('Ausrüstungsset angelegt.');render();}

  function regionUnlocked(id){return (DATA.regions[id]?.unlock||[]).every(req=>requirementMet(req));}
  function travelCost(region){return Math.round(region.travelCost*perkEffect('travelCost')) || 0;}
  function travelRegion(id){const region=DATA.regions[id];if(!region||!regionUnlocked(id))return toast('Diese Region ist noch gesperrt.','error');if(state.actions.athlete)return toast('Beende zuerst die laufende Athletenaktion.','error');const cost=travelCost(region);if(state.player.money<cost)return toast(`Die Reise kostet ${formatMoney(cost)}.`,'error');state.player.money-=cost;state.world.current=id;if(!state.world.visited.includes(id))state.world.visited.push(id);state.player.energy=clamp(state.player.energy-4,0,100);state.player.fatigue=clamp(state.player.fatigue+2,0,100);advanceCalendar(id==='home'?1:2);addXp('organization',80+region.travelCost*.15);logEvent(`Reise nach ${region.name}.`,region.icon);saveState();toast(`${region.name} erreicht.`,'success');navigate('world');}

  function raceUnlocked(race){return race.requirements.every(req=>requirementMet(req));}
  function raceDistanceFactor(race){return DISTANCE_FACTORS[race.distance]||.55;}
  function readiness(){return clamp(.62+state.player.energy/420+state.player.form/480+state.player.morale/900-state.player.fatigue/255,.52,1.2);}
  function focusRaceMultiplier(race){const f=DATA.focuses[state.focusId]||DATA.focuses.balanced,isLong=['Mitteldistanz','Langdistanz'].includes(race.distance);let m=isLong?(f.race.long||1):(f.race.short||1);if(['Technisch','Cross'].includes(race.profile))m*=f.race.technical||1;return m;}
  function raceWeights(race){if(race.specialWeights)return race.specialWeights;if(race.distance==='Langdistanz')return{swim:.095,bike:.50,run:.385,transitions:.02};if(race.distance==='Mitteldistanz')return{swim:.10,bike:.52,run:.35,transitions:.03};return{swim:.12,bike:.50,run:.32,transitions:.06};}
  function weatherForRace(race,hasFuel){const condition=pick(race.conditions||['Ruhig']),gear=equipmentStats();const map={
    Ruhig:{name:'Ruhige Bedingungen',swim:.5,bike:.5,run:.5,risk:.85,text:'Selten war eine Wetter-App so erfreulich langweilig.'},
    Seitenwind:{name:'Starker Seitenwind',swim:0,bike:-2.4+skillLevel('technique')*.08+(gear.handling||0)*.12,run:-.3,risk:1.25,text:'Tiefe Laufräder werden plötzlich zu einer Charakterfrage.'},
    Hitze:{name:'Hitze',swim:-.2,bike:-.7,run:-2.2+skillLevel('nutrition')*.1+(gear.heat||0)*.15+(hasFuel?.8:0),risk:1.2,text:'Der Asphalt glänzt, die Verpflegung wird wichtig.'},
    Regen:{name:'Regen',swim:.3,bike:-1.8+skillLevel('technique')*.09+(gear.handling||0)*.1,run:-.6,risk:1.3,text:'Die Ideallinie ist heute eher ein Vorschlag.'},
    'Unruhiges Wasser':{name:'Unruhiges Wasser',swim:-2+skillLevel('mental')*.1,bike:0,run:0,risk:1.15,text:'Die Bojen bewegen sich vermutlich nicht. Vermutlich.'},
    Kälte:{name:'Kühle Bedingungen',swim:-1.2+(gear.comfort||0)*.1,bike:-.5,run:.4,risk:1.05,text:'Das Wasser ist frisch, der Lauf später angenehm.'}
  };return map[condition]||map.Ruhig;}
  function racePowerEstimate(race){const g=equipmentStats(),df=raceDistanceFactor(race),w=raceWeights(race);const swim=skillLevel('swimming')*1.8+skillLevel('technique')*.6+(g.swim||0);const bike=skillLevel('cycling')*1.8+skillLevel('endurance')*df*.7+skillLevel('aerodynamics')*.35+(g.bike||0)+(g.aero||0)*.5;const run=skillLevel('running')*1.8+skillLevel('endurance')*df*.75+skillLevel('mental')*.35+(g.run||0);const tr=skillLevel('transitions')*1.8+(g.transition||0);return swim*w.swim+bike*w.bike+run*w.run+tr*w.transitions;}
  function raceRecommendation(race){const diff=race.difficulty-racePowerEstimate(race);if(diff<-10)return{label:'Favoritenrolle',class:'success'};if(diff<2)return{label:'Gute Chance',class:'success'};if(diff<10)return{label:'Herausfordernd',class:'warning'};return{label:'Sehr schwer',class:'danger'};}

  function openRacePrep(id){const race=DATA.races.find(r=>r.id===id);if(!race)return;if(!raceUnlocked(race))return toast('Dieses Rennen ist noch gesperrt.','error');const region=DATA.regions[race.region],rival=DATA.rivals[race.rival],record=state.raceRecords[id],rec=raceRecommendation(race);if(state.world.current!==race.region){openDialog(race.name,`<p>Dieses Rennen findet in <strong>${region.name}</strong> statt. Du bist aktuell in ${currentRegion().name}.</p><div class="callout info">Reisekosten: ${formatMoney(travelCost(region))}</div><div class="button-row"><button type="button" class="button full" data-travel-region="${race.region}">Nach ${region.name} reisen</button></div>`);return;}
    const breakdown=readinessBreakdown(race);openDialog(race.name,`<p>${race.description}</p><div class="readiness-detail"><div><span>Körper</span><strong>${breakdown.body}%</strong></div><div><span>Skills</span><strong>${breakdown.skill}%</strong></div><div><span>Gear</span><strong>${breakdown.gear}%</strong></div><div><span>Trainingsplan</span><strong>${breakdown.plan}%</strong></div></div><div class="status-grid compact"><div class="status-card"><small>Bereitschaft</small><div class="metric">${Math.round(readiness()*100)}%</div></div><div class="status-card"><small>Einschätzung</small><div class="metric small-metric ${rec.class}">${rec.label}</div></div><div class="status-card"><small>Bestzeit</small><div class="metric small-metric">${record?.bestTime?formatRaceTime(record.bestTime):'—'}</div></div><div class="status-card"><small>Meisterschaft</small><div class="metric">${state.raceMastery[id]||0}/5</div></div></div>
      ${rival?`<div class="rival-card"><span class="rival-icon">${rival.icon}</span><div><strong>${rival.name}</strong><small>${rival.archetype} · Bilanz ${state.rivalRelations[race.rival]?.wins||0}:${state.rivalRelations[race.rival]?.losses||0}</small></div></div>`:''}
      <div class="form-grid race-plan"><div class="form-field"><label>Schwimmplan</label><select id="swimPlan"><option value="calm">Kontrolliert starten</option><option value="draft">Wasserschatten suchen</option><option value="front">Vorne positionieren</option></select></div><div class="form-field"><label>Radplan</label><select id="bikePlan"><option value="controlled">Leistung konservieren</option><option value="balanced" selected>Ausgewogen fahren</option><option value="attack">Auf dem Rad angreifen</option></select></div><div class="form-field"><label>Laufplan</label><select id="runPlan"><option value="negative">Negativer Split</option><option value="even" selected>Gleichmäßig</option><option value="push">Früh Druck machen</option></select></div>
      <div class="form-field"><label>Fuel</label><select id="raceFuel"><option value="none">Keine Zusatzverpflegung</option>${['homemade_gel','premium_gel','caffeine_gel'].map(x=>`<option value="${x}" ${itemQuantity(x)?'':'disabled'}>${DATA.items[x].name} (${itemQuantity(x)})</option>`).join('')}</select></div><div class="form-field"><label>Hydration</label><select id="raceHydration"><option value="none">Standardversorgung</option><option value="electrolyte_drink" ${itemQuantity('electrolyte_drink')?'':'disabled'}>Elektrolytgetränk (${itemQuantity('electrolyte_drink')})</option></select></div><div class="form-field"><label>Schutz</label><select id="raceProtection"><option value="none">Kein Zusatz</option><option value="repair_kit" ${itemQuantity('repair_kit')?'':'disabled'}>Reparaturset (${itemQuantity('repair_kit')})</option><option value="tire_sealant" ${itemQuantity('tire_sealant')?'':'disabled'}>Dichtmilch (${itemQuantity('tire_sealant')})</option><option value="anti_chafe" ${itemQuantity('anti_chafe')?'':'disabled'}>Anti-Scheuer-Balsam (${itemQuantity('anti_chafe')})</option><option value="carbon_repair_capsule" ${itemQuantity('carbon_repair_capsule')?'':'disabled'}>Carbon-Notfallkapsel (${itemQuantity('carbon_repair_capsule')})</option></select></div></div>
      <div class="button-row"><button type="button" class="button full" data-run-race="${race.id}">Startgebühr ${formatMoney(race.entryFee)} · Rennen starten</button></div>`);
  }

  function runRace(id,plans){const race=DATA.races.find(r=>r.id===id);if(!race||!raceUnlocked(race)||state.world.current!==race.region)return;if(state.player.money<race.entryFee)return toast('Startgebühr nicht verfügbar.','error');if(state.player.energy<24)return toast('Zu wenig Energie.','error');if(state.player.fatigue>88)return toast('Zu hohe Ermüdung.','error');
    const consumed={};['fuel','hydration','protection'].forEach(k=>{const item=plans[k];if(item&&item!=='none'&&removeItem(item,1))consumed[k]=item;});state.player.money-=race.entryFee;audio('race');
    const gear=equipmentStats(),df=raceDistanceFactor(race),weights=raceWeights(race),sponsor=activeSponsor(),mastery=1+(state.raceMastery[id]||0)*.004,focus=focusRaceMultiplier(race),ready=readiness();
    const swimPlans={calm:{speed:.99,risk:.65},draft:{speed:1.025,risk:.9},front:{speed:1.055,risk:1.4}};const bikePlans={controlled:{speed:.975,risk:.68,run:1.035},balanced:{speed:1,risk:1,run:1},attack:{speed:1.06,risk:1.5,run:.94}};const runPlans={negative:{speed:.99,risk:.7,late:1.04},even:{speed:1,risk:1,late:1},push:{speed:1.045,risk:1.45,late:.96}};
    const sp=swimPlans[plans.swim]||swimPlans.calm,bp=bikePlans[plans.bike]||bikePlans.balanced,rp=runPlans[plans.run]||runPlans.even;
    let fuel=consumed.fuel==='premium_gel'?1.75:consumed.fuel==='caffeine_gel'?1.45:consumed.fuel==='homemade_gel'?1:0;fuel*=sponsor?.effect?.fuelEffect||1;fuel*=perkEffect('fuel');const hydration=consumed.hydration?1:0;const weather=weatherForRace(race,fuel+hydration>0);
    if(weather.name==='Hitze'&&hasPerk('heat_protocol'))weather.run*=perkEffect('heatPenalty');
    const common=focus*mastery*trainingRaceMultiplier();let swim=(skillLevel('swimming')*1.85+skillLevel('technique')*.62+skillLevel('endurance')*df*.5+skillLevel('mental')*.3+(gear.swim||0)+weather.swim)*common*sp.speed*perkEffect('swim');
    let bike=(skillLevel('cycling')*1.85+skillLevel('technique')*.47+skillLevel('endurance')*df*.72+skillLevel('aerodynamics')*.38+skillLevel('mechanics')*.13+(gear.bike||0)+(gear.aero||0)*.55*perkEffect('aero')+(gear.handling||0)*.2+weather.bike)*common*bp.speed;
    let run=(skillLevel('running')*1.85+skillLevel('technique')*.52+skillLevel('endurance')*df*.78+skillLevel('strength')*.22+skillLevel('mental')*.38+skillLevel('nutrition')*df*.35+(gear.run||0)+(gear.comfort||0)*df*.12+weather.run+fuel*.85*df+hydration*.45*df)*common*bp.run*rp.speed*rp.late;
    if(plans.run==='negative'&&hasPerk('negative_split'))run*=perkEffect('safeRun');if(state.player.morale<40&&hasPerk('comeback_engine')){swim*=perkEffect('lowMorale');bike*=perkEffect('lowMorale');run*=perkEffect('lowMorale');}
    const transition=(skillLevel('transitions')*1.9+skillLevel('organization')*.25+(gear.transition||0))*perkEffect('transition');
    const scoreFactor=score=>clamp(1+(race.difficulty-score)*.024,.70,1.78)/ready;const splits={swim:race.baseSeconds*weights.swim*scoreFactor(swim)*(.97+Math.random()*.06),bike:race.baseSeconds*weights.bike*scoreFactor(bike)*(.97+Math.random()*.06),run:race.baseSeconds*weights.run*scoreFactor(run)*(.97+Math.random()*.06),transitions:race.baseSeconds*weights.transitions*clamp(1+(race.difficulty*.65-transition)*.025,.52,1.85)};
    const events=[`${weather.name}: ${weather.text}`];const risk=(sp.risk+bp.risk+rp.risk)/3;let mechRisk=clamp((.035+race.difficulty/650-((gear.reliability||0)+skillLevel('mechanics')*.55)/420)*risk*weather.risk,.008,.19)*perkEffect('mechanicalRisk');if(consumed.protection==='tire_sealant')mechRisk*=.45;if(consumed.protection==='carbon_repair_capsule')mechRisk*=.28;
    if(Math.random()<mechRisk){if(['repair_kit','carbon_repair_capsule'].includes(consumed.protection))events.push('Ein Defekt wurde mit dem vorbereiteten Reparaturset begrenzt.');else{splits.bike*=1.06;events.push('Ein Defekt kostete Zeit auf dem Rad.');}}
    let nutritionRisk=clamp((df*.13-skillLevel('nutrition')*.004-fuel*.021-hydration*.012)*risk,0,.19)*perkEffect('nutritionRisk');if(Math.random()<nutritionRisk){splits.run*=1.08;events.push(fuel?'Trotz Fueling wurde der Magen unruhig.':'Zu wenig Verpflegung: Der Lauf wurde lang.');}
    let pressureRisk=clamp((race.difficulty/500-skillLevel('mental')/320)*sp.risk,0,.13)*perkEffect('pressureRisk');if(Math.random()<pressureRisk){splits.swim*=1.045;events.push('Der Start war hektischer als geplant.');}
    if(consumed.protection==='anti_chafe'&&df>=.8)events.push('Der Anti-Scheuer-Balsam rettete den späten Laufkomfort.');
    if(events.length===1)events.push(pick(['Der Rennplan hielt über alle Disziplinen.','Keine großen Zwischenfälle – Vorbereitung gewann.','Ein Angriff im Feld verpuffte später.']));
    const total=Object.values(splits).reduce((a,b)=>a+b,0),competitors=Array.from({length:race.fieldSize-1},()=>race.baseSeconds*(.82+Math.random()*.42));const placement=1+competitors.filter(t=>t<total).length;
    const relation=state.rivalRelations[race.rival]||{wins:0,losses:0,respect:0};const rivalryGrowth=1+Math.min(5,relation.wins)*.008;const rivalTime=race.baseSeconds*(.88+Math.random()*.17)/rivalryGrowth;const beatRival=total<rivalTime;if(race.rival){events.push(beatRival?`${DATA.rivals[race.rival].name} um ${formatRaceTime(rivalTime-total)} geschlagen.`:`${DATA.rivals[race.rival].name} war ${formatRaceTime(total-rivalTime)} schneller.`);state.rivalRelations[race.rival]={wins:relation.wins+(beatRival?1:0),losses:relation.losses+(beatRival?0:1),respect:clamp(relation.respect+(beatRival?3:1),0,100)};if(beatRival){state.counters.rivals_beaten++;state.counters[`rival_${race.rival}_wins`]=(state.counters[`rival_${race.rival}_wins`]||0)+1;}}
    const ratio=1-(placement-1)/Math.max(1,race.fieldSize-1),rewardFactor=.45+ratio*.85;let money=Math.round(race.rewards.money*rewardFactor),rep=Math.max(2,Math.round(race.rewards.reputation*rewardFactor)),fans=Math.max(1,Math.round(race.rewards.fans*rewardFactor));if(sponsor?.effect?.regionalMoney&&race.series==='Regional')money=Math.round(money*sponsor.effect.regionalMoney);if(sponsor?.effect?.internationalCareer&&['International','Langdistanz','Qualifikation','Weltmeisterschaft','Elite'].includes(race.series)){rep=Math.round(rep*sponsor.effect.internationalCareer);fans=Math.round(fans*sponsor.effect.internationalCareer);}if(sponsor?.effect?.extremeRace&&['Extrem','Bergig','Etappe'].includes(race.profile)){money=Math.round(money*sponsor.effect.extremeRace);rep=Math.round(rep*sponsor.effect.extremeRace);}money+=sponsor?.raceBonus||0;money=Math.round(money*legacyMultiplier('finance',.03));
    state.player.money+=money;state.player.reputation+=rep;state.player.fans+=fans;state.season.points+=Math.round((race.rewards.seasonPoints||0)*rewardFactor);state.player.energy=clamp(state.player.energy-Math.round(18+df*28),0,100);let raceFatigue=(race.fatigue||30)*(1-state.facilities.recovery*.045)*legacyMultiplier('recovery',-.02)*perkEffect('raceFatigue')*(sponsor?.effect?.raceFatigue||1);state.player.fatigue=clamp(state.player.fatigue+raceFatigue,0,100);state.player.form=clamp(state.player.form+(placement<=Math.ceil(race.fieldSize*.25)?4:2),0,100);state.player.morale=clamp(state.player.morale+(placement<=3?10:placement<=race.fieldSize/2?3:-2),0,100);
    const xp=160+race.difficulty*14;addXp('swimming',xp*weights.swim*2.1);addXp('cycling',xp*weights.bike*1.15);addXp('running',xp*weights.run*1.45);addXp('transitions',xp*weights.transitions*2.2);addXp('racecraft',xp*.38);addXp('mental',xp*df*.18);addXp('endurance',xp*df*.34);if(df>=.8)addXp('nutrition',xp*.13);
    state.counters.race_finishes++;state.counters[`race_finish_${id}`]=(state.counters[`race_finish_${id}`]||0)+1;if(race.distance==='Langdistanz')state.counters.long_finishes++;if(['International','Elite','Etappenrennen','Weltmeisterschaft'].includes(race.series))state.counters.international_finishes++;if(placement===1){state.counters.race_wins++;state.counters[`race_win_${id}`]=(state.counters[`race_win_${id}`]||0)+1;}if(id==='hawaii_worlds'&&placement<=10)state.counters.hawaii_top10++;if(state.targetRaceId===id){state.counters.target_races_finished=(state.counters.target_races_finished||0)+1;state.counters.prototype_milestones=(state.counters.prototype_milestones||0)+1;}
    const old=state.raceRecords[id]||{bestTime:null,bestPlacement:999,wins:0,finishes:0};state.raceRecords[id]={bestTime:old.bestTime?Math.min(old.bestTime,total):total,bestPlacement:Math.min(old.bestPlacement,placement),wins:old.wins+(placement===1?1:0),finishes:old.finishes+1};state.raceMastery[id]=clamp((state.raceMastery[id]||0)+(placement<=Math.ceil(race.fieldSize*.35)?1:0),0,5);
    const drops=[];for(const drop of race.drops||[]){const chance=drop.chance*legacyMultiplier('scouting',.06);if(Math.random()<chance){if(drop.item){addItem(drop.item,1);drops.push(DATA.items[drop.item].name);}if(drop.material){state.materials[drop.material]=(state.materials[drop.material]||0)+1;drops.push(DATA.materials[drop.material].name);}}}degradeEquipment(df);advanceCalendar(race.calendarDays||2);checkSponsorContract(false);
    const result={raceId:id,time:total,placement,date:Date.now(),splits,events,drops,money,rep,fans,weather:weather.name};state.raceHistory.unshift(result);state.raceHistory=state.raceHistory.slice(0,100);logEvent(`${race.name}: Platz ${placement}/${race.fieldSize} in ${formatRaceTime(total)}.`,'⚑');saveState();closeDialog();render();audio(placement===1||drops.some(x=>DATA.items[Object.keys(DATA.items).find(id=>DATA.items[id].name===x)]?.rarity==='legendary')?'rare':'success');showRaceResult(race,result,rivalTime,beatRival);}
  function showRaceResult(race,result,rivalTime,beatRival){openDialog('Rennergebnis',`<div class="result-hero"><small>${race.name}</small><div class="result-placement">#${result.placement}<small> von ${race.fieldSize}</small></div><strong>${formatRaceTime(result.time)}</strong></div><div class="split-list">${Object.entries(result.splits).filter(([,v])=>v>0).map(([k,v])=>`<div class="split-row"><span>${{swim:'Schwimmen',bike:'Radfahren',run:'Laufen',transitions:'Wechsel'}[k]}</span><strong>${formatRaceTime(v)}</strong></div>`).join('')}</div><div class="event-log">${result.events.map(e=>`<p>• ${e}</p>`).join('')}</div><div class="callout success-callout">+${formatMoney(result.money)} · +${result.rep} Reputation · +${result.fans} Fans${result.drops.length?`<br><strong>Loot:</strong> ${result.drops.join(', ')}`:''}</div><div class="button-row"><button type="button" class="button full" data-close-dialog>Weiter</button></div>`);}

  function shopUnlocked(entry){const r=entry.requirement||{};return(!r.reputation||state.player.reputation>=r.reputation)&&(!r.region||state.world.current===r.region);}
  function buyShopEntry(index,dealIndex=null){const entry=DATA.shop[index];if(!entry||!shopUnlocked(entry))return;ensureMarket();const deal=dealIndex===null?null:state.market.deals[dealIndex],bought=dealIndex===null?0:(state.market.purchases[dealIndex]||0);if(deal&&bought>=deal.stock)return toast('Dieses Tagesangebot ist ausverkauft.','error');let price=entry.price*perkEffect('shopPrice')*(1-(deal?.discount||0));if(state.world.current==='home')price*=1-currentRegion().shopDiscount;price*=1-state.facilities.warehouse*.025;price=Math.round(price);if(state.player.money<price)return toast('Nicht genug Geld.','error');state.player.money-=price;if(entry.type==='item')addItem(entry.id,1);else state.materials[entry.id]=(state.materials[entry.id]||0)+(entry.quantity||1);if(dealIndex!==null)state.market.purchases[dealIndex]=bought+1;state.counters.market_purchases=(state.counters.market_purchases||0)+1;saveState();toast('Einkauf abgeschlossen.','success');render();}

  function sponsorUnlocked(s){return Object.entries(s.requirements||{}).every(([key,v])=>key==='reputation'?state.player.reputation>=v:key==='fans'?state.player.fans>=v:skillLevel(key)>=v);}
  function sponsorCounter(s=activeSponsor()){return s?counterValue(s.contract.counter):0;}
  function signSponsor(id){const sponsor=DATA.sponsors.find(s=>s.id===id);if(!sponsor||!sponsorUnlocked(sponsor))return;state.sponsor={id,baseline:counterValue(sponsor.contract.counter),level:1,contracts:0};state.player.money+=sponsor.signingBonus;addXp('sponsorship',180);logEvent(`Vertrag mit ${sponsor.name} unterschrieben.`,'🤝');saveState();toast(`${sponsor.name}: +${formatMoney(sponsor.signingBonus)} Handgeld.`,'success');render();}
  function sponsorProgress(){const s=activeSponsor();if(!s)return{current:0,target:0};return{current:Math.max(0,sponsorCounter(s)-state.sponsor.baseline),target:Math.ceil(s.contract.target*(1+(state.sponsor.level-1)*.15))};}
  function checkSponsorContract(show=true){const s=activeSponsor();if(!s)return false;const p=sponsorProgress();if(p.current<p.target)return false;let reward=structuredClone(s.contract.reward||{});const mult=perkEffect('sponsorReward');if(reward.money)reward.money=Math.round(reward.money*mult);if(reward.reputation)reward.reputation=Math.round(reward.reputation*mult);if(reward.fans)reward.fans=Math.round(reward.fans*mult);applyRewards(reward,{silent:true});state.sponsor.baseline=sponsorCounter(s);state.sponsor.level++;state.sponsor.contracts++;state.counters.sponsor_contracts++;addXp('sponsorship',220+state.sponsor.level*30);logEvent(`Sponsorvertrag ${s.name} erfüllt.`,'🤝');if(show)toast('Sponsorvertrag erfüllt und Belohnung erhalten.','rare');return true;}
  function setFocus(id){if(!DATA.focuses[id])return;state.focusId=id;saveState();toast(`Trainingsfokus: ${DATA.focuses[id].name}.`);render();}
  function upgradeFacility(id){const f=DATA.facilities[id],level=state.facilities[id]||0;if(!f||level>=f.maxLevel)return;const cost=f.costs[level+1];if(state.player.money<cost)return toast(`Ausbau kostet ${formatMoney(cost)}.`,'error');state.player.money-=cost;state.facilities[id]=level+1;saveState();toast(`${f.name} erreicht Level ${level+1}.`,'rare');render();}
  function legacyUpgrade(id){const up=DATA.legacyUpgrades[id],level=state.legacy[id]||0;if(!up||level>=up.max)return;const cost=up.cost[level];if(state.player.legacyPoints<cost)return toast(`${cost} Legacy-Punkte benötigt.`,'error');state.player.legacyPoints-=cost;state.legacy[id]++;saveState();toast(`${up.name} verbessert.`,'rare');render();}
  function perkUnlocked(id){const r=DATA.perks[id]?.requirements||{};if(r.skill&&skillLevel(r.skill[0])<r.skill[1])return false;if(r.reputation&&state.player.reputation<r.reputation)return false;return true;}
  function togglePerk(id){if(!perkUnlocked(id))return toast('Perk noch gesperrt.','error');if(hasPerk(id))state.activePerks=state.activePerks.filter(x=>x!==id);else{if(state.activePerks.length>=perkSlots())return toast(`Maximal ${perkSlots()} aktive Perks.`,'error');state.activePerks.push(id);}saveState();render();}

  function questAvailable(q){return !q.prerequisite||state.claimedQuests.includes(q.prerequisite);}
  function questProgress(q){return counterValue(q.requirement.counter);}
  function applyRewards(rewards={},options={}){state.player.money+=rewards.money||0;state.player.reputation+=rewards.reputation||0;state.player.fans+=rewards.fans||0;Object.entries(rewards.xp||{}).forEach(([id,n])=>addXp(id,n));Object.entries(rewards.materials||{}).forEach(([id,n])=>state.materials[id]=(state.materials[id]||0)+n);if(rewards.item)addItem(rewards.item[0],rewards.item[1]);if(!options.silent)audio('success');}
  function claimQuest(id){const q=DATA.quests.find(x=>x.id===id);if(!q||state.claimedQuests.includes(id)||!questAvailable(q)||questProgress(q)<q.requirement.target)return;applyRewards(q.rewards);state.claimedQuests.push(id);logEvent(`Quest abgeschlossen: ${q.title}.`,'📜');saveState();toast(`Quest abgeschlossen: ${q.title}.`,'rare');render();}
  function achievementProgress(a){const r=a.requirement;if(r.type==='counter')return counterValue(r.id);if(r.type==='collection')return state.seenItems.length;if(r.type==='skill')return skillLevel(r.id);if(r.type==='anySkill')return Math.max(...Object.keys(DATA.skills).map(skillLevel));if(r.type==='allSkills')return Math.min(...r.ids.map(skillLevel));if(r.type==='quests')return state.claimedQuests.length;if(r.type==='money')return state.player.money;if(r.type==='reputation')return state.player.reputation;if(r.type==='raceWin')return state.raceRecords[r.id]?.wins||0;if(r.type==='visitedRegions')return state.world.visited.length;if(r.type==='activePerks')return state.activePerks.length;if(r.type==='facilityMax')return Object.entries(state.facilities).filter(([id,l])=>l>=DATA.facilities[id].maxLevel).length;if(r.type==='careerDay')return state.player.careerDay;if(r.type==='item')return itemQuantity(r.id);return 0;}
  function claimAchievement(id){const a=DATA.achievements.find(x=>x.id===id);if(!a||state.claimedAchievements.includes(id)||achievementProgress(a)<a.requirement.value)return;applyRewards(a.rewards);state.claimedAchievements.push(id);saveState();toast(`Erfolg: ${a.title}.`,'rare');render();}
  function dailyProgress(m){return Math.max(0,counterValue(m.counter)-(m.start||0));}
  function claimDaily(index){const m=state.daily.missions[index];if(!m||state.daily.claimed.includes(index)||dailyProgress(m)<m.target)return;applyRewards(m.reward);state.daily.claimed.push(index);saveState();toast('Tagesziel abgeschlossen.','success');render();}
  function claimDailyBonus(){if(state.daily.bonusClaimed||state.daily.claimed.length<state.daily.missions.length)return;const streak=state.daily.streak+1;state.daily.streak=streak;state.daily.lastCompletedDate=state.daily.date;state.daily.bonusClaimed=true;applyRewards({money:160+streak*12,reputation:8,materials:{blueprint:streak%5===0?1:0}});saveState();toast(`Tagesbonus · Serie ${streak}.`,'rare');render();}
  function weeklyMissionProgress(m){return Math.min(...m.requirements.map(r=>Math.max(0,counterValue(r.counter)-(m.starts[r.counter]||0))/r.target));}
  function claimWeekly(index){const m=state.weekly.missions[index];if(!m||state.weekly.claimed.includes(index)||weeklyMissionProgress(m)<1)return;applyRewards(m.reward);state.weekly.claimed.push(index);saveState();toast('Wochenziel abgeschlossen.','rare');render();}

  function careerTitle(){const r=state.player.reputation;if(r>=1200)return'Weltstar';if(r>=700)return'Eliteprofi';if(r>=400)return'Internationaler Profi';if(r>=220)return'Nationaler Profi';if(r>=90)return'Erfahrener Age-Grouper';if(r>=25)return'Regionaler Athlet';return'Lokaler Amateur';}
  function licenseName(){const p=state.season.points;if(p>=600)return'Elite';if(p>=340)return'International';if(p>=180)return'National';if(p>=80)return'Regional';return'Verein';}
  function coachingAdvice(){const target=targetRace();if(state.player.fatigue>72)return{title:'Regeneration priorisieren',text:'Deine Ermüdung begrenzt aktuell Training und Rennen.',route:'training'};if(state.player.energy<35)return{title:'Energie auffüllen',text:'Eine Regenerationseinheit verhindert schlechte Trainingsqualität.',route:'training'};const lowest=['swimming','cycling','running'].sort((a,b)=>skillLevel(a)-skillLevel(b))[0];if(skillLevel(lowest)+3<Math.max(skillLevel('swimming'),skillLevel('cycling'),skillLevel('running')))return{title:`${DATA.skills[lowest].name} nachziehen`,text:'Dein schwächster Disziplinskill limitiert ausgewogene Rennen.',route:'training'};if(target){const br=readinessBreakdown(target),nextAction=coachNextAction();if(br.total<78&&nextAction)return{title:`${nextAction.title} für ${target.name}`,text:`Zielbereitschaft ${br.total} %. ${nextAction.description}`,route:'training'};return{title:`Zielrennen: ${target.name}`,text:`Bereitschaft ${br.total} %. ${DATA.regions[target.region].name} · ${target.distance}`,route:'races'};}const next=DATA.races.find(r=>raceUnlocked(r)&&state.raceRecords[r.id]?.finishes===undefined);if(next)return{title:`Nächstes Ziel: ${next.name}`,text:`${DATA.regions[next.region].name} · ${next.distance}`,route:'races'};return{title:'Build verfeinern',text:'Perks, Equipment und Regionsboni bieten jetzt den größten Hebel.',route:'more'};}

  function progress(percent,kind=''){return `<div class="progress-track"><div class="progress-fill ${kind}" style="width:${clamp(percent,0,100)}%"></div></div>`;}
  function pageHeader(title,description){return `<header class="page-header"><h1>${title}</h1><p>${description}</p></header>`;}
  function tabs(items,active,dataKey){return `<div class="category-tabs">${items.map(x=>`<button class="tab-button ${x===active?'active':''}" data-${dataKey}="${escapeHtml(x)}">${x}</button>`).join('')}</div>`;}
  function actionSlot(slot,label){const run=state.actions[slot];if(!run)return `<div class="card mini-card"><small>${label}</small><h3>Slot frei</h3><p>Wähle eine passende Aktion.</p></div>`;const a=getAction(slot,run.id),remain=(run.endsAt-Date.now())/1000,percent=100-(remain/actionDuration(slot,a))*100;return `<div class="card mini-card action-card busy"><small>${label}</small><h3>${a.icon} ${a.title}</h3>${progress(percent,'success')}<div class="progress-labels"><span>${formatDuration(remain)}</span><button class="text-button" data-cancel-action="${slot}">Abbrechen</button></div></div>`;}

  function renderTrainingBalance(compact=false){const result=trainingBalance(),rows=Object.keys(result.targets).map(key=>{const value=result.loads[key]||0,target=result.targets[key],pct=value/target*100;return `<div class="load-row"><div><span>${LOAD_LABELS[key]}</span><small>${Math.round(value)}/${target}</small></div>${progress(pct,pct>135?'warning':pct>=75?'success':'')}</div>`;}).join('');return `<section class="card training-balance ${compact?'compact':''}"><div class="card-title-row"><div><small>Trainingszyklus ${state.trainingCycle.number}</small><h3>Planabdeckung ${result.score} %</h3></div><span class="score-ring ${result.overload>.25?'danger':result.score>=72?'success':''}">${result.score}</span></div>${rows}<p class="muted">${result.overload>.25?'Überlastungsrisiko: Erholung priorisieren.':result.score>=72?'Der aktuelle Mix unterstützt Form und Zielrennen.':'Fehlende Reize gezielt ergänzen – nicht einfach nur mehr trainieren.'}</p></section>`;}
  function renderTargetRace(){const race=targetRace();if(!race)return `<section class="card target-card empty-target"><div><small>Zielrennen</small><h3>Noch kein konkretes Ziel</h3><p>Ein Zielrennen verbessert Coach-Empfehlungen und zeigt eine echte Bereitschaftsanalyse.</p></div><button class="button" data-route="races">Ziel auswählen</button></section>`;const br=readinessBreakdown(race);return `<section class="card target-card"><div class="card-title-row"><div><small>${DATA.regions[race.region].icon} Zielrennen · ${race.distance}</small><h3>${race.name}</h3></div><span class="score-ring ${br.total>=80?'success':br.total<60?'danger':''}">${br.total}</span></div><div class="readiness-breakdown"><span>Körper <strong>${br.body}%</strong></span><span>Skills <strong>${br.skill}%</strong></span><span>Gear <strong>${br.gear}%</strong></span><span>Plan <strong>${br.plan}%</strong></span></div><div class="button-row"><button class="button" data-race-prep="${race.id}">Vorbereitung</button><button class="button secondary" data-route="races">Anderes Ziel</button></div></section>`;}
  function renderTrainingPlanner(){const action=coachNextAction(),race=targetRace();return `<div class="planner-grid">${renderTrainingBalance()}<section class="card coach-plan"><div class="card-title-row"><div><small>Coach-Plan</small><h3>${race?`Vorbereitung auf ${race.name}`:'Grundlage aufbauen'}</h3></div><span class="big-icon">🎯</span></div>${action?`<p><strong>Nächster sinnvoller Reiz:</strong> ${action.title}</p><p>${action.description}</p><button class="button full" data-start-action="athlete:${action.id}" ${state.actions.athlete?'disabled':''}>${state.actions.athlete?'Athleten-Slot belegt':'Empfehlung starten'}</button>`:'<p>Aktuell ist Regeneration oder ein frei gewählter Schwerpunkt sinnvoll.</p>'}<div class="callout info">Der Plan bewertet Belastungsmix, Zielrennen, Ermüdung und deine schwächste Disziplin. Er automatisiert nichts – die Entscheidung bleibt bei dir.</div></section></div>`;}
  function renderHome(){const advice=coachingAdvice(),tier=seasonTier(),next=nextSeasonTier(),region=currentRegion(),sponsor=activeSponsor();return `${pageHeader('Karrierezentrum','Training, Material, Reisen und Karriere greifen in einem gemeinsamen Saisonverlauf ineinander.')}
    <section class="hero-card career-hero"><div class="eyebrow">Saison ${state.season.number} · Tag ${state.season.day}/${state.season.length}</div><h1>${escapeHtml(state.player.name)}, der Weg nach Hawaii ist offen.</h1><p>${careerTitle()} · ${licenseName()}-Lizenz · Aktuell in ${region.name}</p><div class="hero-actions"><button class="button" data-route="training">Training planen</button><button class="button secondary" data-route="races">Rennen wählen</button></div></section>
    <div class="status-grid dashboard-metrics"><div class="status-card"><small>Bereitschaft</small><div class="metric">${Math.round(readiness()*100)}%</div>${progress(readiness()*100,readiness()<.75?'warning':'success')}</div><div class="status-card"><small>Energie</small><div class="metric">${Math.round(state.player.energy)}</div>${progress(state.player.energy)}</div><div class="status-card"><small>Ermüdung</small><div class="metric">${Math.round(state.player.fatigue)}</div>${progress(state.player.fatigue,state.player.fatigue>65?'warning':'')}</div><div class="status-card"><small>Form</small><div class="metric">${Math.round(state.player.form)}</div>${progress(state.player.form)}</div></div>
    <div class="dashboard-core-grid">${renderTargetRace()}${renderTrainingBalance(true)}</div>
    <section class="card coach-card"><div class="card-title-row"><div><small>Coach-Empfehlung</small><h3>${advice.title}</h3><p>${advice.text}</p></div><span class="big-icon">🎯</span></div><div class="button-row"><button class="button secondary" data-route="${advice.route}">Öffnen</button></div></section>
    <div class="section-title"><h2>Aktive Prozesse</h2><small>3 parallele Slots</small></div><div class="card-grid three">${actionSlot('athlete','Athlet')}${actionSlot('workshop','Werkstatt')}${actionSlot('career','Karriere')}</div>
    <div class="section-title"><h2>Saison & Welt</h2><small>${tier.name}</small></div><div class="card-grid two"><section class="card"><div class="card-title-row"><div><small>Saisonwertung</small><h3>${state.season.points} Punkte</h3></div><span class="big-icon">🏆</span></div>${progress(next?state.season.points/next.min*100:100,'success')}<p>${next?`Noch ${next.min-state.season.points} Punkte bis ${next.name}.`:'Höchste Saisonklasse erreicht.'}</p></section><section class="card"><div class="card-title-row"><div><small>Aktuelle Region</small><h3>${region.icon} ${region.name}</h3><p>${region.subtitle}</p></div></div><div class="button-row"><button class="button secondary" data-route="world">Weltkarte</button></div></section></div>
    <div class="section-title"><h2>Tagesziele</h2><small>Serie ${state.daily.streak}</small></div>${renderDaily()}
    <div class="section-title"><h2>Wochenziele</h2><small>Langfristiger Rhythmus</small></div>${renderWeekly()}
    <div class="section-title"><h2>Karrierefluss</h2><small>${sponsor?sponsor.name:'Kein Sponsor'}</small></div><div class="card timeline">${state.log.length?state.log.slice(0,5).map(x=>`<div class="timeline-row"><span>${x.icon}</span><div><strong>${x.text}</strong><small>${new Date(x.time).toLocaleString('de-DE',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}</small></div></div>`).join(''):'<div class="empty-state">Deine Karrieregeschichte beginnt mit der ersten Aktion.</div>'}</div>`;}
  function renderDaily(){return `<div class="mission-grid">${state.daily.missions.map((m,i)=>{const p=dailyProgress(m),done=state.daily.claimed.includes(i);return `<section class="card mission-card ${done?'quest-done':''}"><div class="card-title-row"><h3>${m.icon} ${m.title}</h3><span>${Math.min(p,m.target)}/${m.target}</span></div>${progress(p/m.target*100,done?'success':'')}${done?'<p>Belohnung erhalten.</p>':`<button class="button full" data-claim-daily="${i}" ${p<m.target?'disabled':''}>Belohnung</button>`}</section>`;}).join('')}</div><div class="daily-bonus"><span>Alle Tagesziele: Bonus und Serienfortschritt</span><button class="button" data-claim-daily-bonus ${state.daily.claimed.length<3||state.daily.bonusClaimed?'disabled':''}>${state.daily.bonusClaimed?'Erhalten':'Bonus holen'}</button></div>`;}
  function renderWeekly(){return `<div class="card-grid two">${state.weekly.missions.map((m,i)=>{const p=weeklyMissionProgress(m),done=state.weekly.claimed.includes(i);return `<section class="card mission-card ${done?'quest-done':''}"><div class="card-title-row"><h3>${m.icon} ${m.title}</h3><span>${Math.round(Math.min(1,p)*100)}%</span></div>${progress(p*100,done?'success':'')}<p>${m.requirements.map(r=>`${r.counter.replaceAll('_',' ')} ${Math.min(r.target,Math.max(0,counterValue(r.counter)-(m.starts[r.counter]||0)))}/${r.target}`).join(' · ')}</p><button class="button full" data-claim-weekly="${i}" ${p<1||done?'disabled':''}>${done?'Erhalten':'Wochenbelohnung'}</button></section>`;}).join('')}</div>`;}

  function actionCard(action,slot){const locked=!actionRequirementsMet(action),energy=actionEnergy(action),running=state.actions[slot];return `<article class="card action-card ${locked?'locked':''}"><div class="card-title-row"><div><small>${action.group||action.tags?.[0]||'Aktion'} · ${action.calendarDays||1} Karrieretag(e)</small><h3>${action.icon} ${action.title}</h3></div><span class="pill">${formatDuration(actionDuration(slot,action))}</span></div><p>${action.description}</p><div class="action-meta">${energy?`<span class="pill ${energy<0?'warning':'accent'}">${energy>0?'+':''}${energy} Energie</span>`:''}${action.fatigue?`<span class="pill">${action.fatigue>0?'+':''}${action.fatigue} Ermüdung</span>`:''}${Object.entries(action.xp||{}).slice(0,3).map(([id,n])=>`<span class="pill">${DATA.skills[id]?.icon||'✦'} ${Math.round(n)} XP</span>`).join('')}${slot==='athlete'?Object.entries(inferTrainingLoad(action)).slice(0,2).map(([k,v])=>`<span class="pill load-pill">${LOAD_LABELS[k]} +${Math.round(v)}</span>`).join(''):''}</div>${locked?`<div class="callout">Gesperrt: ${actionLockText(action)}</div>`:`<button class="button full" data-start-action="${slot}:${action.id}" ${running?'disabled':''}>${running?'Slot belegt':'Starten'}</button>`}</article>`;}
  function renderTraining(){const groups=['Alle',...new Set(DATA.athleteActions.map(a=>a.group))],actions=DATA.athleteActions.filter(a=>ui.trainingGroup==='Alle'||a.group===ui.trainingGroup);const content=ui.trainingTab==='plan'?renderTrainingPlanner():`${tabs(groups,ui.trainingGroup,'training-group')}<div class="card-grid two">${actions.map(a=>actionCard(a,'athlete')).join('')}</div>`;return `${pageHeader('Training','Plane nicht nur einzelne Einheiten: Belastungsmix, Erholung und Zielrennen formen gemeinsam deine Leistungsentwicklung.')}${actionSlot('athlete','Athletenaktion')}<div class="readiness-strip"><span>Energie <strong>${Math.round(state.player.energy)}</strong></span><span>Ermüdung <strong>${Math.round(state.player.fatigue)}</strong></span><span>Form <strong>${Math.round(state.player.form)}</strong></span><span>Region <strong>${currentRegion().name}</strong></span></div><div class="category-tabs"><button class="tab-button ${ui.trainingTab==='plan'?'active':''}" data-training-tab="plan">Trainingsplan</button><button class="tab-button ${ui.trainingTab==='actions'?'active':''}" data-training-tab="actions">Alle Einheiten</button></div>${content}`;}

  function renderRaces(){const series=['Alle',...new Set(DATA.races.map(r=>r.series))],regions=['Alle','Aktuelle Region',...new Set(DATA.races.map(r=>DATA.regions[r.region].name))];let races=DATA.races.filter(r=>(ui.raceSeries==='Alle'||r.series===ui.raceSeries)&&(ui.raceRegion==='Alle'||(ui.raceRegion==='Aktuelle Region'?r.region===state.world.current:DATA.regions[r.region].name===ui.raceRegion)));return `${pageHeader('Wettkämpfe','Jede Distanz verlangt ein anderes Verhältnis aus Skills, Material, Fueling und Risiko. Reise zum Austragungsort, bevor du startest.')}${tabs(series,ui.raceSeries,'race-series')}${tabs(regions,ui.raceRegion,'race-region')}<div class="card-grid two">${races.map(r=>raceCard(r)).join('')}</div>`;}
  function raceCard(race){const unlocked=raceUnlocked(race),rec=raceRecommendation(race),record=state.raceRecords[race.id],away=state.world.current!==race.region;return `<article class="card race-card ${unlocked?'':'locked'}"><div class="card-title-row"><div><small>${DATA.regions[race.region].icon} ${DATA.regions[race.region].name} · ${race.series}</small><h3>${race.name}</h3></div><span class="pill ${rec.class}">${rec.label}</span></div><p>${race.description}</p><div class="race-route"><div><strong>${race.swim}</strong><small>Swim</small></div><div><strong>${race.bike}</strong><small>Bike</small></div><div><strong>${race.run}</strong><small>Run</small></div></div><div class="record-row"><span>Gebühr <strong>${formatMoney(race.entryFee)}</strong></span><span>Profil <strong>${race.profile}</strong></span><span>Bestzeit <strong>${record?.bestTime?formatRaceTime(record.bestTime):'—'}</strong></span></div>${!unlocked?`<ul class="requirement-list">${race.requirements.map(x=>`<li class="${requirementMet(x)?'requirement-ok':'requirement-no'}">${x.text}</li>`).join('')}</ul>`:`<div class="button-row"><button class="button ${away?'secondary':''}" data-race-prep="${race.id}">${away?'Reise & Vorbereitung':'Rennvorbereitung'}</button><button class="button ghost" data-set-target="${race.id}" ${state.targetRaceId===race.id?'disabled':''}>${state.targetRaceId===race.id?'Zielrennen':'Als Ziel'}</button></div>`}</article>`;}

  function renderWorld(){return `${pageHeader('Weltkarte','Regionen sind mehr als Kulissen: Sie verändern Training, Händler, Rennen und Produktionsketten.') }<section class="card world-current"><div class="card-title-row"><div><small>Aktueller Standort</small><h3>${currentRegion().icon} ${currentRegion().name}</h3><p>${currentRegion().description}</p></div><span class="map-pulse"></span></div></section><div class="world-grid">${Object.entries(DATA.regions).map(([id,r])=>regionCard(id,r)).join('')}</div>`;}
  function regionCard(id,r){const unlocked=regionUnlocked(id),current=id===state.world.current,visited=state.world.visited.includes(id);return `<article class="card region-card ${current?'selected-card':''} ${unlocked?'':'locked'}"><div class="region-visual">${r.icon}</div><div><small>${visited?'Besucht':'Unentdeckt'}${current?' · Aktuell':''}</small><h3>${r.name}</h3><p>${r.subtitle}</p><div class="action-meta">${(r.bonuses?.skills||[]).map(s=>`<span class="pill accent">+${Math.round(((r.bonuses.xp||1)-1)*100)}% ${DATA.skills[s].name}</span>`).join('')}</div>${unlocked?(current?'<button class="button full" disabled>Aktueller Standort</button>':`<button class="button full" data-travel-region="${id}">Reisen · ${formatMoney(travelCost(r))}</button>`):`<ul class="requirement-list">${r.unlock.map(x=>`<li class="${requirementMet(x)?'requirement-ok':'requirement-no'}">${x.text}</li>`).join('')}</ul>`}</div></article>`;}

  function itemStatsHtml(id){return Object.entries(DATA.items[id].stats||{}).map(([k,v])=>`<span class="${v<0?'negative-stat':''}">${STAT_NAMES[k]||k} ${v>0?'+':''}${v}</span>`).join('');}
  function renderGear(){const tabsList=['equipment','consumables','materials','shop','loadouts','collection'],labels={equipment:'Ausrüstung',consumables:'Verbrauch',materials:'Materialien',shop:'Shop',loadouts:'Sets',collection:'Sammlung'};const content={equipment:renderEquipment,consumables:renderConsumables,materials:renderMaterials,shop:renderShop,loadouts:renderLoadouts,collection:renderCollection}[ui.gearTab]();return `${pageHeader('Ausrüstung & Inventar','Qualität, Zustand, Upgrades und Streckenprofil entscheiden gemeinsam – nicht nur der Seltenheitsgrad.')}<div class="category-tabs">${tabsList.map(x=>`<button class="tab-button ${ui.gearTab===x?'active':''}" data-gear-tab="${x}">${labels[x]}</button>`).join('')}</div>${content}`;}
  function renderEquipment(){const items=state.inventory.filter(x=>DATA.items[x.itemId]?.slot);return `<div class="button-row utility-row"><button class="button secondary" data-repair-all>Gesamte Ausrüstung warten</button></div><div class="card-grid two">${items.map(entry=>{const id=entry.itemId,item=DATA.items[id],meta=getItemMeta(id),equipped=state.equipped[item.slot]===id;return `<article class="card item-card ${equipped?'equipped':''}"><div class="item-icon">${item.icon}</div><div><div class="card-title-row"><div><small class="rarity-${item.rarity}">${RARITY_NAMES[item.rarity]} · ${DATA.equipmentSlots[item.slot]?.name}</small><h3>${item.name}${meta.upgrade?` +${meta.upgrade}`:''}</h3></div><span class="quality-stars">${'★'.repeat(meta.quality||1)}</span></div><p>${item.description}</p><div class="item-stats">${itemStatsHtml(id)}</div><div class="condition-row"><span>Zustand ${Math.round(meta.condition)}%</span><span>Meisterschaft ${Math.min(30,meta.mastery||0)}/30</span></div>${progress(meta.condition,meta.condition<45?'warning':'')}<div class="button-row"><button class="button" data-equip-item="${id}" ${equipped?'disabled':''}>${equipped?'Ausgerüstet':'Ausrüsten'}</button><button class="button secondary" data-upgrade-item="${id}" ${meta.upgrade>=3?'disabled':''}>Upgrade</button><button class="button ghost" data-sell-item="${id}">Verkaufen</button></div></div></article>`;}).join('')}</div>`;}
  function renderConsumables(){const items=state.inventory.filter(x=>DATA.items[x.itemId]?.consumable);return items.length?`<div class="card-grid two">${items.map(e=>{const item=DATA.items[e.itemId];return `<article class="card item-card"><div class="item-icon">${item.icon}</div><div><small class="rarity-${item.rarity}">${RARITY_NAMES[item.rarity]} · ${e.quantity}×</small><h3>${item.name}</h3><p>${item.description}</p><div class="button-row"><button class="button secondary" data-use-item="${e.itemId}" ${item.consumable==='recovery'?'':'disabled'}>${item.consumable==='recovery'?'Jetzt nutzen':'Rennitem'}</button></div></div></article>`;}).join('')}</div>`:'<div class="empty-state">Keine Verbrauchsgegenstände vorhanden.</div>';}
  function renderMaterials(){return `<section class="card resource-list">${Object.entries(DATA.materials).map(([id,m])=>`<div class="list-row"><span><strong>${m.icon} ${m.name}</strong><small>Basiswert ${formatMoney(m.value)}</small></span><strong>${formatNumber(state.materials[id]||0)}</strong></div>`).join('')}</section>`;}
  function renderShop(){ensureMarket();return `<div class="callout info">Der Markt rotiert täglich. Preisvorteile hängen zusätzlich von Region, Lager, Reputation und Karriere-Perks ab.</div><div class="section-title"><h2>Tagesmarkt</h2><small>${new Date().toLocaleDateString('de-DE')}</small></div><div class="card-grid two">${state.market.deals.map((deal,dealIndex)=>{const e=DATA.shop[deal.index],obj=e.type==='item'?DATA.items[e.id]:DATA.materials[e.id],locked=!shopUnlocked(e),bought=state.market.purchases[dealIndex]||0,sold=bought>=deal.stock;let price=Math.round(e.price*perkEffect('shopPrice')*(1-state.facilities.warehouse*.025)*(1-deal.discount));return `<article class="card shop-card ${locked||sold?'locked':''}"><div class="card-title-row"><div><small>${deal.discount?`-${Math.round(deal.discount*100)} % Tagesdeal`:'Standardpreis'} · ${Math.max(0,deal.stock-bought)} verfügbar</small><h3>${obj.icon} ${obj.name}</h3></div><strong>${formatMoney(price)}</strong></div><p>${e.type==='item'?(obj.description||'Ausrüstung'):`${e.quantity||1} Einheit(en) Material`}</p>${locked?`<div class="callout">Aktuell nicht verfügbar: Reputation oder Region fehlt.</div>`:`<button class="button full" data-buy-shop="${deal.index}" data-deal-index="${dealIndex}" ${sold?'disabled':''}>${sold?'Ausverkauft':'Kaufen'}</button>`}</article>`;}).join('')}</div>`;}
  function renderLoadouts(){const labels={sprint:'Sprint-Set',middle:'Mitteldistanz-Set',long:'Langdistanz-Set'};return `<div class="card-grid three">${Object.entries(labels).map(([id,label])=>`<article class="card"><h3>${label}</h3><p>${state.loadouts[id]?'Gespeichertes Set vorhanden.':'Noch nicht gespeichert.'}</p><div class="button-row"><button class="button secondary" data-save-loadout="${id}">Aktuelles speichern</button><button class="button" data-apply-loadout="${id}" ${state.loadouts[id]?'':'disabled'}>Anlegen</button></div></article>`).join('')}</div>`;}
  function renderCollection(){return `<div class="collection-summary"><strong>${state.seenItems.length}/${Object.keys(DATA.items).length}</strong><span>entdeckt</span>${progress(state.seenItems.length/Object.keys(DATA.items).length*100)}</div><div class="collection-grid">${Object.entries(DATA.items).map(([id,item])=>`<div class="collection-item ${state.seenItems.includes(id)?'seen':'unseen'}"><span>${state.seenItems.includes(id)?item.icon:'?'}</span><small>${state.seenItems.includes(id)?item.name:'Unentdeckt'}</small></div>`).join('')}</div>`;}

  function renderSkills(){const cats=['Alle',...new Set(Object.values(DATA.skills).map(s=>s.category))],skills=Object.entries(DATA.skills).filter(([,s])=>ui.skillCategory==='Alle'||s.category===ui.skillCategory);return `${pageHeader('Skills & Build','18 Skills bilden die Grundlage. Aktive Perks machen daraus einen persönlichen Build.')}${tabs(cats,ui.skillCategory,'skill-category')}<div class="card-grid two">${skills.map(([id,s])=>{const p=skillProgress(id);return `<article class="card skill-card"><div class="skill-icon">${s.icon}</div><div><small>${s.category}</small><h3>${s.name}</h3>${progress(p.percent)}<div class="progress-labels"><span>${formatNumber(p.current)} XP</span><span>${formatNumber(p.needed)} XP</span></div></div><div class="skill-level"><strong>${p.level}</strong><small>LEVEL</small></div></article>`;}).join('')}</div><div class="section-title"><h2>Aktive Perks</h2><small>${state.activePerks.length}/${perkSlots()} Slots</small></div><div class="card-grid two">${Object.entries(DATA.perks).map(([id,p])=>{const unlocked=perkUnlocked(id),active=hasPerk(id);return `<article class="card perk-card ${active?'selected-card':''} ${unlocked?'':'locked'}"><div class="card-title-row"><div><small>${p.category}</small><h3>${p.icon} ${p.name}</h3></div>${active?'<span class="pill accent">AKTIV</span>':''}</div><p>${p.description}</p>${unlocked?`<button class="button ${active?'secondary':''} full" data-toggle-perk="${id}">${active?'Deaktivieren':'Aktivieren'}</button>`:`<div class="callout">Benötigt ${p.requirements.skill?`${DATA.skills[p.requirements.skill[0]].name} Level ${p.requirements.skill[1]}`:`${p.requirements.reputation} Reputation`}</div>`}</article>`;}).join('')}</div>`;}
  function renderWorkshop(){return `${actionSlot('workshop','Werkstattaktion')}<div class="card-grid two">${DATA.workshopActions.map(a=>actionCard(a,'workshop')).join('')}</div>`;}
  function renderCareer(){const sponsor=activeSponsor(),p=sponsorProgress();return `<div class="section-title"><h2>Sponsorvertrag</h2><small>${sponsor?sponsor.tier:'Frei'}</small></div>${sponsor?`<section class="card selected-card"><div class="card-title-row"><h3>${sponsor.icon} ${sponsor.name}</h3><span>${p.current}/${p.target}</span></div><p>${sponsor.perk}</p>${progress(p.current/p.target*100,'success')}<button class="button full" data-claim-sponsor ${p.current<p.target?'disabled':''}>Vertrag abrechnen</button></section>`:'<div class="callout info">Noch kein Sponsor aktiv. Wähle einen Vertrag mit sinnvollen Zielkonflikten.</div>'}<div class="section-title"><h2>Sponsoren</h2></div><div class="card-grid two">${DATA.sponsors.map(s=>{const unlocked=sponsorUnlocked(s),selected=state.sponsor.id===s.id;return `<article class="card ${selected?'selected-card':''} ${unlocked?'':'locked'}"><div class="card-title-row"><h3>${s.icon} ${s.name}</h3><span class="pill">${s.tier}</span></div><p>${s.description}</p><div class="callout info sponsor-perk">${s.perk}</div><button class="button full" data-sign-sponsor="${s.id}" ${!unlocked||selected?'disabled':''}>${selected?'Aktiv':`Vertrag · ${formatMoney(s.signingBonus)}`}</button></article>`;}).join('')}</div><div class="section-title"><h2>Karriereaktionen</h2></div>${actionSlot('career','Karriereaktion')}<div class="card-grid two">${DATA.careerActions.map(a=>actionCard(a,'career')).join('')}</div>`;}
  function renderQuests(){const chains=['Alle',...new Set(DATA.quests.map(q=>q.chain))],quests=DATA.quests.filter(q=>ui.questChain==='Alle'||q.chain===ui.questChain);return `${tabs(chains,ui.questChain,'quest-chain')}<div class="card-grid two">${quests.map(q=>{const available=questAvailable(q),done=state.claimedQuests.includes(q.id),p=questProgress(q),target=q.requirement.target;return `<article class="card ${done?'quest-done':''} ${available?'':'locked'}"><div class="card-title-row"><div><small>${q.chain} · Kapitel ${q.chapter}</small><h3>${q.icon} ${q.title}</h3></div>${done?'<span class="pill accent">FERTIG</span>':''}</div><p>${q.story}</p>${available?`${progress(p/target*100,done?'success':'')}<div class="progress-labels"><span>${q.requirement.label}</span><span>${Math.min(p,target)}/${target}</span></div><button class="button full" data-claim-quest="${q.id}" ${p<target||done?'disabled':''}>${done?'Abgeschlossen':'Belohnung beanspruchen'}</button>`:`<div class="callout">Vorherige Quest erforderlich.</div>`}</article>`;}).join('')}</div>`;}
  function renderAchievements(){return `<div class="card-grid two">${DATA.achievements.map(a=>{const p=achievementProgress(a),done=state.claimedAchievements.includes(a.id);return `<article class="card ${done?'quest-done':''}"><div class="card-title-row"><h3>${a.icon} ${a.title}</h3><span>${Math.min(p,a.requirement.value)}/${a.requirement.value}</span></div><p>${a.description}</p>${progress(p/a.requirement.value*100,done?'success':'')}<button class="button full" data-claim-achievement="${a.id}" ${p<a.requirement.value||done?'disabled':''}>${done?'Erhalten':'Belohnung'}</button></article>`;}).join('')}</div>`;}
  function renderFacilities(){return `<div class="card-grid two">${Object.entries(DATA.facilities).map(([id,f])=>{const level=state.facilities[id]||0,cost=level<f.maxLevel?f.costs[level+1]:0;return `<article class="card"><div class="card-title-row"><div><small>Level ${level}/${f.maxLevel}</small><h3>${f.icon} ${f.name}</h3></div></div><p>${f.description}</p>${progress(level/f.maxLevel*100,'success')}<button class="button full" data-upgrade-facility="${id}" ${level>=f.maxLevel?'disabled':''}>${level>=f.maxLevel?'Maximal ausgebaut':`Ausbauen · ${formatMoney(cost)}`}</button></article>`;}).join('')}</div>`;}
  function renderLegacy(){return `<div class="callout info">Legacy-Punkte entstehen am Saisonende. Sie verbessern dauerhaft alle folgenden Saisons.</div><div class="status-card legacy-balance"><small>Verfügbar</small><div class="metric">${state.player.legacyPoints} ✦</div></div><div class="card-grid two">${Object.entries(DATA.legacyUpgrades).map(([id,u])=>{const level=state.legacy[id]||0,cost=level<u.max?u.cost[level]:0;return `<article class="card"><div class="card-title-row"><h3>${u.icon} ${u.name}</h3><span>${level}/${u.max}</span></div><p>${u.description}</p><button class="button full" data-legacy-upgrade="${id}" ${level>=u.max?'disabled':''}>${level>=u.max?'Maximal':`${cost} Legacy-Punkt(e)`}</button></article>`;}).join('')}</div>`;}
  function renderStats(){const totalLevels=Object.keys(DATA.skills).reduce((s,id)=>s+skillLevel(id),0);return `<div class="status-grid"><div class="status-card"><small>Karrieretag</small><div class="metric">${state.player.careerDay}</div></div><div class="status-card"><small>Gesamtlevel</small><div class="metric">${totalLevels}</div></div><div class="status-card"><small>Finishes</small><div class="metric">${state.counters.race_finishes}</div></div><div class="status-card"><small>Siege</small><div class="metric">${state.counters.race_wins}</div></div></div><div class="section-title"><h2>Letzte Rennen</h2></div><section class="card">${state.raceHistory.length?state.raceHistory.slice(0,12).map(x=>{const r=DATA.races.find(q=>q.id===x.raceId);return `<div class="list-row"><span><strong>${r?.name||x.raceId}</strong><small>${new Date(x.date).toLocaleDateString('de-DE')} · ${formatRaceTime(x.time)}</small></span><strong>#${x.placement}</strong></div>`;}).join(''):'<div class="empty-state">Noch keine Rennen.</div>'}</section>`;}
  function renderMore(){const ids=['skills','workshop','career','quests','achievements','facilities','legacy','stats'],labels={skills:'Skills',workshop:'Werkstatt',career:'Karriere',quests:'Quests',achievements:'Erfolge',facilities:'Basis',legacy:'Legacy',stats:'Statistik'};const renderer={skills:renderSkills,workshop:renderWorkshop,career:renderCareer,quests:renderQuests,achievements:renderAchievements,facilities:renderFacilities,legacy:renderLegacy,stats:renderStats}[ui.moreTab];return `${pageHeader(labels[ui.moreTab],'Vertiefe deinen Build, deine Produktionsketten und die langfristige Karriere.') }<div class="category-tabs">${ids.map(id=>`<button class="tab-button ${ui.moreTab===id?'active':''}" data-more-tab="${id}">${labels[id]}</button>`).join('')}</div>${renderer()}`;}

  function render(){ensureDaily();ensureWeekly();ensureTrainingCycle();ensureMarket();processCompletedActions(false);window.GameAudio?.setTheme(state.world.current);const pages={home:renderHome,training:renderTraining,races:renderRaces,world:renderWorld,gear:renderGear,more:renderMore};ui.main.innerHTML=(pages[ui.route]||renderHome)();setTimeout(showPendingDecision,0);document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.route===ui.route));updateHeader();}
  function updateHeader(){document.getElementById('moneyValue').textContent=formatMoney(state.player.money);document.getElementById('reputationValue').textContent=formatNumber(state.player.reputation);document.getElementById('fansValue').textContent=formatNumber(state.player.fans);document.getElementById('winsValue').textContent=formatNumber(state.counters.race_wins);document.getElementById('careerLabel').textContent=`${state.player.name} · ${careerTitle()}`;}
  function navigate(route){if(!['home','training','races','world','gear','more'].includes(route))return;ui.route=route;render();ui.main.focus({preventScroll:true});window.scrollTo({top:0,behavior:state.settings.reducedMotion?'auto':'smooth'});}
  function openDialog(title,html){ui.dialogTitle.textContent=title;ui.dialogContent.innerHTML=html;if(!ui.dialog.open)ui.dialog.showModal();}
  function closeDialog(){if(ui.dialog.open)ui.dialog.close();}
  function toast(message,type=''){const n=document.createElement('div');n.className=`toast ${type}`;n.textContent=message;ui.toast.appendChild(n);if(type==='error')audio('error');setTimeout(()=>n.remove(),3800);}
  function showTutorial(){openDialog('Willkommen bei Complete Career',`<div class="setup-hero"><span>🏊 🚴 🏃</span><h3>Deine Karriere beginnt lokal – dein System entscheidet, wie weit sie führt.</h3></div><div class="form-grid"><div class="form-field"><label>Athletenname</label><input id="setupNameInput" maxlength="24" value="${escapeHtml(state.player.name==='Rookie'?'':state.player.name)}" placeholder="Dein Name"></div><div class="form-field"><label>Erster Schwerpunkt</label><select id="setupFocusInput"><option value="balanced">Ausgewogen – empfohlen</option><option value="shortCourse">Sprint & Standard</option><option value="longCourse">Mittel- & Langdistanz</option><option value="craftAthlete">Werkstatt & Eigenbau</option><option value="publicFigure">Karriere & Sponsoren</option></select></div></div><div class="tutorial-steps"><div><strong>Trainiere mit Plan</strong><p>Jede Einheit zählt in einen siebentägigen Belastungszyklus.</p></div><div><strong>Setze Zielrennen</strong><p>Coach, Ausrüstung und Rennvorbereitung reagieren auf dein konkretes Ziel.</p></div><div><strong>Triff Entscheidungen</strong><p>Dynamische Ereignisse verbinden Training, Werkstatt und Karriere.</p></div><div><strong>Baue deine Dynasty</strong><p>Loot, Prototypen, Regionen, Rivalen und Saisons bleiben langfristig relevant.</p></div></div><div class="button-row"><button class="button full" data-finish-tutorial>Karriere starten</button></div>`);}
  function openSettings(){openDialog('Einstellungen & Spielstand',`<div class="form-grid"><div class="form-field"><label>Name</label><input id="playerNameInput" maxlength="24" value="${escapeHtml(state.player.name)}"></div><button class="button" data-save-name>Name speichern</button>${deferredInstallPrompt?'<button class="button secondary" data-install-app>App installieren</button>':''}<label class="list-row"><span><strong>Soundeffekte</strong><small>Feedback für Aktionen, Drops und Rennen.</small></span><input id="soundInput" type="checkbox" ${state.settings.sound?'checked':''}></label><label class="list-row"><span><strong>Ambient-Musik</strong><small>Minimaler synthetischer Hintergrundklang.</small></span><input id="musicInput" type="checkbox" ${state.settings.music?'checked':''}></label><label class="volume-control"><span>Effektlautstärke <strong>${Math.round(state.settings.soundVolume*100)}%</strong></span><input id="soundVolumeInput" type="range" min="0" max="100" value="${Math.round(state.settings.soundVolume*100)}"></label><label class="volume-control"><span>Musiklautstärke <strong>${Math.round(state.settings.musicVolume*100)}%</strong></span><input id="musicVolumeInput" type="range" min="0" max="40" value="${Math.round(state.settings.musicVolume*100)}"></label><label class="list-row"><span><strong>Haptisches Feedback</strong><small>Kurze Vibrationen bei Entscheidungen und besonderen Erfolgen.</small></span><input id="hapticsInput" type="checkbox" ${state.settings.haptics?'checked':''}></label><label class="list-row"><span><strong>Reduzierte Bewegung</strong><small>Weniger Animationen.</small></span><input id="reducedMotionInput" type="checkbox" ${state.settings.reducedMotion?'checked':''}></label><button class="button secondary" data-show-tutorial>Tutorial anzeigen</button><button class="button secondary" data-export-save>Spielstand exportieren</button><label class="button secondary import-label">Spielstand importieren<input id="importSaveInput" type="file" accept="application/json" hidden></label><button class="button secondary" data-restore-backup>Letztes Saison-Backup laden</button><button class="button danger" data-reset-save>Neues Spiel</button></div><div class="callout info" style="margin-top:14px">Version ${DATA.version}. Vollständiges neues Repository-Paket. Automatische Migration älterer lokaler Spielstände und Saison-Backups sind aktiv.</div>`);}
  function exportSave(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`triathlon-karriere-v2-save-${todayKey()}.json`;a.click();URL.revokeObjectURL(url);}
  async function importSave(file){try{const parsed=JSON.parse(await file.text());state=mergeState(makeDefaultState(),parsed);ensureDaily();ensureWeekly();ensureTrainingCycle();ensureMarket();saveState();closeDialog();render();toast('Spielstand importiert.','success');}catch(_){toast('Ungültiger Spielstand.','error');}}
  function restoreBackup(){try{const backup=JSON.parse(localStorage.getItem(BACKUP_KEY)||'null');if(!backup)return toast('Kein Saison-Backup vorhanden.','error');state=mergeState(makeDefaultState(),backup);saveState();closeDialog();render();toast('Saison-Backup geladen.','success');}catch(_){toast('Backup konnte nicht geladen werden.','error');}}
  function resetSave(){if(!confirm('Gesamten lokalen Spielstand löschen?'))return;state=makeDefaultState();ensureDaily();ensureWeekly();ensureTrainingCycle();ensureMarket();saveState();closeDialog();render();setTimeout(showTutorial,100);}
  async function installApp(){if(!deferredInstallPrompt)return;deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;closeDialog();}

  document.addEventListener('click',event=>{window.GameAudio?.ensure();const t=event.target.closest('button,[data-route],label');if(!t)return;if(!t.disabled&&t.dataset.closeDialog===undefined)audio('click');if(t.dataset.route)return navigate(t.dataset.route);if(t.id==='settingsButton')return openSettings();if(t.dataset.startAction){const[slot,id]=t.dataset.startAction.split(':');return startAction(slot,id);}if(t.dataset.cancelAction)return cancelAction(t.dataset.cancelAction);if(t.dataset.racePrep)return openRacePrep(t.dataset.racePrep);if(t.dataset.runRace)return runRace(t.dataset.runRace,{swim:document.getElementById('swimPlan')?.value,bike:document.getElementById('bikePlan')?.value,run:document.getElementById('runPlan')?.value,fuel:document.getElementById('raceFuel')?.value,hydration:document.getElementById('raceHydration')?.value,protection:document.getElementById('raceProtection')?.value});if(t.dataset.travelRegion)return travelRegion(t.dataset.travelRegion);if(t.dataset.equipItem)return equipItem(t.dataset.equipItem);if(t.dataset.useItem)return useItem(t.dataset.useItem);if(t.dataset.sellItem)return sellItem(t.dataset.sellItem);if(t.dataset.upgradeItem)return upgradeItem(t.dataset.upgradeItem);if(t.dataset.repairAll!==undefined)return repairAll();if(t.dataset.buyShop!==undefined)return buyShopEntry(Number(t.dataset.buyShop),t.dataset.dealIndex===undefined?null:Number(t.dataset.dealIndex));if(t.dataset.saveLoadout)return saveLoadout(t.dataset.saveLoadout);if(t.dataset.applyLoadout)return applyLoadout(t.dataset.applyLoadout);if(t.dataset.trainingTab){ui.trainingTab=t.dataset.trainingTab;return render();}if(t.dataset.trainingGroup){ui.trainingGroup=t.dataset.trainingGroup;return render();}if(t.dataset.raceSeries){ui.raceSeries=t.dataset.raceSeries;return render();}if(t.dataset.raceRegion){ui.raceRegion=t.dataset.raceRegion;return render();}if(t.dataset.gearTab){ui.gearTab=t.dataset.gearTab;return render();}if(t.dataset.moreTab){ui.moreTab=t.dataset.moreTab;return render();}if(t.dataset.skillCategory){ui.skillCategory=t.dataset.skillCategory;return render();}if(t.dataset.questChain){ui.questChain=t.dataset.questChain;return render();}if(t.dataset.claimQuest)return claimQuest(t.dataset.claimQuest);if(t.dataset.claimAchievement)return claimAchievement(t.dataset.claimAchievement);if(t.dataset.claimDaily!==undefined)return claimDaily(Number(t.dataset.claimDaily));if(t.dataset.claimDailyBonus!==undefined)return claimDailyBonus();if(t.dataset.claimWeekly!==undefined)return claimWeekly(Number(t.dataset.claimWeekly));if(t.dataset.setTarget)return setTargetRace(t.dataset.setTarget);if(t.dataset.decisionChoice!==undefined)return resolveDecision(Number(t.dataset.decisionChoice));if(t.dataset.signSponsor)return signSponsor(t.dataset.signSponsor);if(t.dataset.claimSponsor!==undefined){if(checkSponsorContract(true)){saveState();render();}return;}if(t.dataset.setFocus)return setFocus(t.dataset.setFocus);if(t.dataset.upgradeFacility)return upgradeFacility(t.dataset.upgradeFacility);if(t.dataset.legacyUpgrade)return legacyUpgrade(t.dataset.legacyUpgrade);if(t.dataset.togglePerk)return togglePerk(t.dataset.togglePerk);if(t.dataset.closeDialog!==undefined)return closeDialog();if(t.dataset.finishTutorial!==undefined){state.player.name=(document.getElementById('setupNameInput')?.value||state.player.name||'Rookie').trim().slice(0,24)||'Rookie';const setupFocus=document.getElementById('setupFocusInput')?.value;if(setupFocus&&DATA.focuses[setupFocus])state.focusId=setupFocus;state.settings.tutorialDone=true;state.settings.setupDone=true;saveState();closeDialog();render();return;}if(t.dataset.showTutorial!==undefined)return showTutorial();if(t.dataset.saveName!==undefined){state.player.name=(document.getElementById('playerNameInput')?.value||'Rookie').trim().slice(0,24)||'Rookie';saveState();closeDialog();render();return;}if(t.dataset.installApp!==undefined)return installApp();if(t.dataset.exportSave!==undefined)return exportSave();if(t.dataset.restoreBackup!==undefined)return restoreBackup();if(t.dataset.resetSave!==undefined)return resetSave();});
  document.addEventListener('change',event=>{if(event.target.id==='importSaveInput'&&event.target.files?.[0])importSave(event.target.files[0]);if(event.target.id==='hapticsInput'){state.settings.haptics=event.target.checked;saveState();}if(event.target.id==='reducedMotionInput'){state.settings.reducedMotion=event.target.checked;saveState();}if(event.target.id==='soundInput'){state.settings.sound=event.target.checked;window.GameAudio?.configure(state.settings);saveState();}if(event.target.id==='musicInput'){state.settings.music=event.target.checked;window.GameAudio?.configure(state.settings);saveState();}if(event.target.id==='soundVolumeInput'){state.settings.soundVolume=Number(event.target.value)/100;window.GameAudio?.configure(state.settings);saveState();}if(event.target.id==='musicVolumeInput'){state.settings.musicVolume=Number(event.target.value)/100;window.GameAudio?.configure(state.settings);saveState();}});
  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;});window.addEventListener('beforeunload',saveState);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){applyPassiveRecovery(state);ensureDaily();ensureWeekly();ensureTrainingCycle();ensureMarket();const messages=processCompletedActions(true);render();messages.forEach(m=>toast(`Offline: ${m}`,'success'));}else saveState();});
  setInterval(()=>{const second=Math.floor(Date.now()/1000);if(second===lastRenderedSecond)return;lastRenderedSecond=second;const completed=processCompletedActions(false);if(completed.length||Object.values(state.actions).some(Boolean))render();},500);
  if('serviceWorker'in navigator&&location.protocol!=='file:')window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(console.warn));
  window.GameAudio?.configure(state.settings);const offline=processCompletedActions(true);render();offline.forEach(m=>toast(`Offline: ${m}`,'success'));if(!state.settings.tutorialDone)setTimeout(showTutorial,250);
})();
